    args: {},
    handler: async (ctx) => {
        return await ctx.storage.generateUploadUrl();
    },
});

import { v } from "convex/values";
import { mutation, query } from "./_generated/server";
import { Id } from "./_generated/dataModel";

// Apply to become a moderator
export const applyForModerator = mutation({
    args: {
        userId: v.id("users"),
    },
    handler: async (ctx, args) => {
        const user = await ctx.db.get(args.userId);

        if (!user) {
            throw new Error("User not found");
        }

        if (user.role === 'moderator' || user.role === 'admin') {
            throw new Error("You are already a moderator");
        }

        if (user.moderatorStatus?.isActive) {
            throw new Error("You have already applied to be a moderator");
        }

        // Update user with moderator application
        await ctx.db.patch(args.userId, {
            moderatorStatus: {
                appliedAt: Date.now(),
                isActive: true, // Application is pending
            },
        });

        return { success: true, message: "Application submitted successfully" };
    },
});

// Approve a moderator application (admin only)
export const approveModerator = mutation({
    args: {
        userId: v.id("users"),
        adminId: v.id("users"),
    },
    handler: async (ctx, args) => {
        // Verify admin has permission
        const admin = await ctx.db.get(args.adminId);
        if (!admin || admin.role !== 'admin') {
            throw new Error("Unauthorized: Only admins can approve moderators");
        }

        const user = await ctx.db.get(args.userId);
        if (!user) {
            throw new Error("User not found");
        }

        if (!user.moderatorStatus?.isActive) {
            throw new Error("User has not applied to be a moderator");
        }

        // Update user role to moderator
        await ctx.db.patch(args.userId, {
            role: 'moderator',
            moderatorStatus: {
                ...user.moderatorStatus,
                approvedAt: Date.now(),
                approvedBy: args.adminId,
                isActive: true,
            },
        });

        return { success: true, message: "Moderator approved successfully" };
    },
});

// Revoke moderator status (admin only)
export const revokeModerator = mutation({
    args: {
        userId: v.id("users"),
        adminId: v.id("users"),
    },
    handler: async (ctx, args) => {
        // Verify admin has permission
        const admin = await ctx.db.get(args.adminId);
        if (!admin || admin.role !== 'admin') {
            throw new Error("Unauthorized: Only admins can revoke moderators");
        }

        const user = await ctx.db.get(args.userId);
        if (!user) {
            throw new Error("User not found");
        }

        if (user.role !== 'moderator') {
            throw new Error("User is not a moderator");
        }

        // Revert user role to member
        await ctx.db.patch(args.userId, {
            role: 'member',
            moderatorStatus: user.moderatorStatus ? {
                ...user.moderatorStatus,
                isActive: false,
            } : undefined,
        });

        return { success: true, message: "Moderator status revoked" };
    },
});

// Get list of active moderators
export const getModerators = query({
    args: {},
    handler: async (ctx) => {
        const moderators = await ctx.db
            .query("users")
            .withIndex("by_role", (q) => q.eq("role", "moderator"))
            .collect();

        const admins = await ctx.db
            .query("users")
            .withIndex("by_role", (q) => q.eq("role", "admin"))
            .collect();

        return {
            moderators: moderators.map(m => ({
                id: m._id,
                name: m.name,
                handle: m.handle,
                avatar: m.avatar,
                role: m.role,
                approvedAt: m.moderatorStatus?.approvedAt,
            })),
            admins: admins.map(a => ({
                id: a._id,
                name: a.name,
                handle: a.handle,
                avatar: a.avatar,
                role: a.role,
            })),
        };
    },
});

// Get pending moderator applications (admin only)
export const getPendingApplications = query({
    args: {
        adminId: v.id("users"),
    },
    handler: async (ctx, args) => {
        // Verify admin has permission
        const admin = await ctx.db.get(args.adminId);
        if (!admin || admin.role !== 'admin') {
            throw new Error("Unauthorized: Only admins can view applications");
        }

        const allUsers = await ctx.db.query("users").collect();

        const pendingApplications = allUsers.filter(user =>
            user.moderatorStatus?.isActive &&
            !user.moderatorStatus?.approvedAt &&
            user.role !== 'moderator' &&
            user.role !== 'admin'
        );

        return pendingApplications.map(user => ({
            id: user._id,
            name: user.name,
            handle: user.handle,
            avatar: user.avatar,
            appliedAt: user.moderatorStatus!.appliedAt,
        }));
    },
});

// Update user role (admin only - for direct role assignment)
export const updateUserRole = mutation({
    args: {
        userId: v.id("users"),
        adminId: v.id("users"),
        newRole: v.union(v.literal('admin'), v.literal('moderator'), v.literal('member')),
    },
    handler: async (ctx, args) => {
        // Verify admin has permission
        const admin = await ctx.db.get(args.adminId);
        if (!admin || admin.role !== 'admin') {
            throw new Error("Unauthorized: Only admins can update user roles");
        }

        const user = await ctx.db.get(args.userId);
        if (!user) {
            throw new Error("User not found");
        }

        await ctx.db.patch(args.userId, {
            role: args.newRole,
        });

        return { success: true, message: `User role updated to ${args.newRole}` };
    },
});

// Check if user is moderator or admin
export const checkModeratorStatus = query({
    args: {
        userId: v.id("users"),
    },
    handler: async (ctx, args) => {
        const user = await ctx.db.get(args.userId);

        if (!user) {
            return { isModerator: false, isAdmin: false, role: 'member' };
        }

        return {
            isModerator: user.role === 'moderator' || user.role === 'admin',
            isAdmin: user.role === 'admin',
            role: user.role || 'member',
            hasPendingApplication: user.moderatorStatus?.isActive && !user.moderatorStatus?.approvedAt,
        };
    },
});

import { query } from "../_generated/server";
import { v } from "convex/values";
import { getCurrentUser } from "../users/utils";

// Check if specific users are online
export const getOnlineStatus = query({
    args: {
        userIds: v.array(v.id("users")),
    },
    handler: async (ctx, args) => {
        const ONLINE_THRESHOLD = 2 * 60 * 1000; // 2 minutes
        const now = Date.now();

        const statuses = await Promise.all(
            args.userIds.map(async (userId) => {
                const user = await ctx.db.get(userId);
                if (!user) {
                    return { userId, isOnline: false, lastSeen: null };
                }

                // User is online if isOnline flag is true AND lastSeen is within threshold
                const isRecentlyActive = user.lastSeen
                    ? (now - user.lastSeen) < ONLINE_THRESHOLD
                    : false;

                return {
                    userId,
                    isOnline: user.isOnline && isRecentlyActive,
                    lastSeen: user.lastSeen || null,
                };
            })
        );

        return statuses;
    },
});

// Get single user's presence status
export const getUserPresence = query({
    args: {
        userId: v.id("users"),
    },
    handler: async (ctx, args) => {
        const ONLINE_THRESHOLD = 2 * 60 * 1000; // 2 minutes
        const now = Date.now();

        const user = await ctx.db.get(args.userId);
        if (!user) {
            return { isOnline: false, lastSeen: null, lastSeenFormatted: "Never" };
        }

        const isRecentlyActive = user.lastSeen
            ? (now - user.lastSeen) < ONLINE_THRESHOLD
            : false;

        // Format last seen time
        let lastSeenFormatted = "Never";
        if (user.lastSeen) {
            const diff = now - user.lastSeen;
            if (diff < 60000) {
                lastSeenFormatted = "Just now";
            } else if (diff < 3600000) {
                lastSeenFormatted = `${Math.floor(diff / 60000)}m ago`;
            } else if (diff < 86400000) {
                lastSeenFormatted = `${Math.floor(diff / 3600000)}h ago`;
            } else {
                lastSeenFormatted = new Date(user.lastSeen).toLocaleDateString();
            }
        }

        return {
            isOnline: user.isOnline && isRecentlyActive,
            lastSeen: user.lastSeen || null,
            lastSeenFormatted,
        };
    },
});

import { v } from "convex/values";
import { mutation, query } from "./_generated/server";
import { Doc, Id } from "./_generated/dataModel";

// Get pending reports with filtering and sorting
export const getPendingReports = query({
    args: {
        type: v.optional(v.union(v.literal('comment'), v.literal('link'), v.literal('post'))),
        reason: v.optional(v.string()),
        sortBy: v.optional(v.union(v.literal('date'), v.literal('severity'))),
    },
    handler: async (ctx, args) => {
        const reportsQuery = ctx.db.query("reports")
            .withIndex("by_status", (q) => q.eq("status", "pending"));

        const reports = await reportsQuery.collect();

        // Filter by type if specified
        let filteredReports = reports;
        if (args.type) {
            filteredReports = filteredReports.filter(r => r.type === args.type);
        }

        // Filter by reason if specified
        if (args.reason && args.reason !== 'All') {
            filteredReports = filteredReports.filter(r =>
                r.reasons.some(reason => reason.includes(args.reason!))
            );
        }

        // Get reporter information for each report
        const reportsWithReporters = await Promise.all(
            filteredReports.map(async (report) => {
                const reporter = await ctx.db.get(report.reporterId);

                // Count duplicate reports for the same target
                const duplicates = await ctx.db
                    .query("reports")
                    .withIndex("by_target", (q) => q.eq("targetId", report.targetId))
                    .filter((q) => q.neq(q.field("_id"), report._id))
                    .collect();

                return {
                    ...report,
                    reporter: reporter ? {
                        id: reporter._id,
                        handle: reporter.handle,
                        avatar: reporter.avatar,
                        name: reporter.name,
                    } : null,
                    otherReporters: duplicates.length,
                };
            })
        );

        // Sort reports
        if (args.sortBy === 'severity') {
            reportsWithReporters.sort((a, b) => b.otherReporters - a.otherReporters);
        } else {
            // Default: sort by date (newest first)
            reportsWithReporters.sort((a, b) => b.timestamp - a.timestamp);
        }

        return reportsWithReporters;
    },
});

// Submit a new report
export const submitReport = mutation({
    args: {
        type: v.union(v.literal('comment'), v.literal('link'), v.literal('post')),
        targetId: v.string(),
        targetContent: v.string(),
        contextTitle: v.string(),
        contextId: v.optional(v.string()),
        reasons: v.array(v.string()),
        reporterId: v.id("users"),
    },
    handler: async (ctx, args) => {
        // Check if this user has already reported this content
        const existingReport = await ctx.db
            .query("reports")
            .withIndex("by_target", (q) => q.eq("targetId", args.targetId))
            .filter((q) => q.eq(q.field("reporterId"), args.reporterId))
            .first();

        if (existingReport) {
            throw new Error("You have already reported this content");
        }

        const reportId = await ctx.db.insert("reports", {
            type: args.type,
            targetId: args.targetId,
            targetContent: args.targetContent,
            contextTitle: args.contextTitle,
            contextId: args.contextId,
            reasons: args.reasons,
            reporterId: args.reporterId,
            timestamp: Date.now(),
            status: "pending",
        });

        return reportId;
    },
});

// Resolve a report (moderator action)
export const resolveReport = mutation({
    args: {
        reportId: v.id("reports"),
        moderatorId: v.id("users"),
        action: v.string(), // 'Hide', 'Delete', 'Approve', 'Warn User'
        notes: v.optional(v.string()),
    },
    handler: async (ctx, args) => {
        // Verify moderator has permission
        const moderator = await ctx.db.get(args.moderatorId);
        if (!moderator || (moderator.role !== 'moderator' && moderator.role !== 'admin')) {
            throw new Error("Unauthorized: Only moderators can resolve reports");
        }

        const report = await ctx.db.get(args.reportId);
        if (!report) {
            throw new Error("Report not found");
        }

        // Map action to status
        let status: "pending" | "approved" | "hidden" | "deleted" | "warned";
        switch (args.action) {
            case 'Hide':
                status = 'hidden';
                break;
            case 'Delete':
                status = 'deleted';
                break;
            case 'Approve':
                status = 'approved';
                break;
            case 'Warn User':
                status = 'warned';
                break;
            default:
                status = 'approved';
        }

        // Update report status
        await ctx.db.patch(args.reportId, {
            status,
            resolvedAt: Date.now(),
            resolvedBy: args.moderatorId,
            moderatorNotes: args.notes,
        });

        // Log the moderation action
        await ctx.db.insert("moderationActions", {
            reportId: args.reportId,
            moderatorId: args.moderatorId,
            action: args.action,
            timestamp: Date.now(),
            notes: args.notes,
        });

        return { success: true, status };
    },
});

// Get moderation statistics
export const getReportStats = query({
    args: {
        moderatorId: v.optional(v.id("users")),
    },
    handler: async (ctx, args) => {
        const allReports = await ctx.db.query("reports").collect();

        const pendingReports = allReports.filter(r => r.status === 'pending');

        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const todayTimestamp = today.getTime();

        const resolvedToday = allReports.filter(
            r => r.resolvedAt && r.resolvedAt >= todayTimestamp
        );

        // Calculate average resolution time
        const resolvedReports = allReports.filter(r => r.resolvedAt);
        const totalResolutionTime = resolvedReports.reduce((sum, r) => {
            return sum + (r.resolvedAt! - r.timestamp);
        }, 0);
        const avgResolutionTime = resolvedReports.length > 0
            ? Math.round(totalResolutionTime / resolvedReports.length / 60000) // Convert to minutes
            : 0;

        // User-specific stats
        let userResolvedCount = 0;
        if (args.moderatorId) {
            const userActions = await ctx.db
                .query("moderationActions")
                .withIndex("by_moderator", (q) => q.eq("moderatorId", args.moderatorId!))
                .collect();
            userResolvedCount = userActions.length;
        }

        return {
            totalReports: allReports.length,
            pendingReports: pendingReports.length,
            resolvedToday: resolvedToday.length,
            avgResolutionTime,
            userResolvedCount,
        };
    },
});

// Get moderation history/log
export const getReportHistory = query({
    args: {
        moderatorId: v.optional(v.id("users")),
        limit: v.optional(v.number()),
    },
    handler: async (ctx, args) => {
        let actions;

        if (args.moderatorId) {
            actions = await ctx.db.query("moderationActions")
                .withIndex("by_moderator", (q) =>
                    q.eq("moderatorId", args.moderatorId!)
                )
                .order("desc")
                .take(args.limit || 50);
        } else {
            actions = await ctx.db.query("moderationActions")
                .withIndex("by_timestamp")
                .order("desc")
                .take(args.limit || 50);
        }

        // Get full details for each action
        const actionsWithDetails = await Promise.all(
            actions.map(async (action) => {
                const report = await ctx.db.get(action.reportId);
                const moderator = await ctx.db.get(action.moderatorId);

                return {
                    ...action,
                    report: report ? {
                        id: report._id,
                        reasons: report.reasons, // Use reasons array
                        targetContent: report.targetContent,
                    } : null,
                    moderator: moderator ? {
                        name: moderator.name,
                        handle: moderator.handle,
                        avatar: moderator.avatar,
                    } : null,
                };
            })
        );

        return actionsWithDetails;
    },
});

"use client";

import React, { createContext, useContext, ReactNode, useState } from "react";
import { LanguageSkill, ContributionItem, NotificationItem, Challenge } from "@/types";
import { INITIAL_LANGUAGES_STATE, INITIAL_CONTRIBUTIONS, INITIAL_NOTIFICATIONS } from "@/data/mock";
import { MOCK_CHALLENGES } from "@/data/mockChallenges";

interface MockUser {
  id: string;
  fullName: string;
  username: string;
  imageUrl: string;
  primaryEmailAddress: {
    emailAddress: string;
  };
}

// --- Mock Clerk ---
interface UserContextType {
  user: MockUser | null;
  isLoaded: boolean;
  isSignedIn: boolean;
  languages: LanguageSkill[];
  setLanguages: React.Dispatch<React.SetStateAction<LanguageSkill[]>>;
  myContributions: ContributionItem[];
  setMyContributions: React.Dispatch<React.SetStateAction<ContributionItem[]>>;
  notifications: NotificationItem[];
  setNotifications: React.Dispatch<React.SetStateAction<NotificationItem[]>>;
  unreadCount: number;
  markAllAsRead: () => void;
  markAsRead: (id: string) => void;
  challenges: Challenge[];
  addChallenge: (challenge: Challenge) => void;
}

const MockUserContext = createContext<UserContextType | null>(null);

// --- Mock Global State (Singleton pattern for persistence across remounts) ---
let globalMyContributions: ContributionItem[] = [...INITIAL_CONTRIBUTIONS];
let globalNotifications: NotificationItem[] = [...INITIAL_NOTIFICATIONS];
let globalChallenges: Challenge[] = [...MOCK_CHALLENGES];

export const ClerkProvider = ({ children }: { children: ReactNode }) => {
  const [languages, setLanguages] = useState<LanguageSkill[]>(INITIAL_LANGUAGES_STATE);
  const [myContributions, setMyContributionsInternal] = useState<ContributionItem[]>(globalMyContributions);
  const [notifications, setNotificationsInternal] = useState<NotificationItem[]>(globalNotifications);
  const [challenges, setChallengesInternal] = useState<Challenge[]>(globalChallenges);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  // Sync internal state with global singleton
  const setMyContributions = (val: React.SetStateAction<ContributionItem[]>) => {
    if (typeof val === 'function') {
      globalMyContributions = val(globalMyContributions);
    } else {
      globalMyContributions = val;
    }
    setMyContributionsInternal(globalMyContributions);
  };

  const setNotifications = (val: React.SetStateAction<NotificationItem[]>) => {
    if (typeof val === 'function') {
      globalNotifications = val(globalNotifications);
    } else {
      globalNotifications = val;
    }
    setNotificationsInternal(globalNotifications);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const markAsRead = (id: string) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
  };

  const addChallenge = (challenge: Challenge) => {
    globalChallenges = [challenge, ...globalChallenges];
    setChallengesInternal(globalChallenges);
  };


  const mockUser = {
    id: "user_2mock",
    fullName: "Mock User",
    username: "mockuser",
    imageUrl: "https://lh3.googleusercontent.com/aida-public/AB6AXuDKkfM9WqTPsqCfuM1KQIQ1QzsbiAaq2rab_EQ2MwL_8b9sbJ3-mIl3CjDCR888PPrsBNhkpl7tkden40rCqo3pJe3Sepe18k46KUvejTidyoAK941vcqejBnqRrcfC5hPZop_XFQ7S9jkteso1RvDSjv8s1JfGwGhOYE1uQ1M1J93quDxOniTqTNGD-1WZq2GOu_Z1EpzGjMzNeyvhYbuIwiqYK1TDLfGX5mpdg--_df6DoewiFO-RhrraeKpwY7MetQ94avb6spo",
    primaryEmailAddress: { emailAddress: "mock@example.com" },
  };

  return (
    <MockUserContext.Provider value={{
      user: mockUser,
      isLoaded: true,
      isSignedIn: true,
      languages,
      setLanguages,
      myContributions,
      setMyContributions,
      notifications,
      setNotifications,
      unreadCount,
      markAllAsRead,
      markAsRead,
      challenges,
      addChallenge
    }}>
      {children}
    </MockUserContext.Provider>
  );
};

export const useUser = () => {
  const context = useContext(MockUserContext);
  return context || {
    user: null,
    isLoaded: true,
    isSignedIn: false,
    languages: [],
    setLanguages: () => { },
    myContributions: [],
    setMyContributions: () => { },
    notifications: [],
    setNotifications: () => { },
    unreadCount: 0,
    markAllAsRead: () => { },
    markAsRead: () => { },
