"use client";

import { useAuth } from "@clerk/nextjs";
import { useRouter } from "next/navigation";
import { useEffect, ReactNode } from "react";

interface AuthGuardProps {
  children: ReactNode;
  fallback?: ReactNode;
}

export function AuthGuard({ children, fallback }: AuthGuardProps) {
  const { userId, isLoaded } = useAuth();
  const router = useRouter();

  useEffect(() => {
    // Only redirect if auth is loaded and user is definitely not authenticated
    if (isLoaded && !userId) {
      // Don't redirect immediately - allow guest access
      // The guest check is handled below
    }
  }, [isLoaded, userId, router]);

  if (!isLoaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background-dark">
        <div className="flex flex-col items-center gap-4">
          <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
          <p className="text-stone-400 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  // Allow access if user is authenticated OR if no auth is required (guest mode)
  // The actual permission checking is done server-side in Convex mutations
  return <>{children}</>;
}

interface GuestGuardProps {
  children: ReactNode;
}

export function GuestGuard({ children }: GuestGuardProps) {
  const { userId, isLoaded } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (isLoaded && userId) {
      router.push("/dashboard");
    }
  }, [isLoaded, userId, router]);

  if (!isLoaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background-dark">
        <div className="flex flex-col items-center gap-4">
          <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
          <p className="text-stone-400 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  if (userId) {
    return null;
  }

  return <>{children}</>;
}

"use client";

import { useSignIn, useSignUp } from "@clerk/nextjs";
import { useRouter } from "next/navigation";

interface AuthSocialButtonsProps {
  onSignInClick: () => void;
  onSignUpClick: () => void;
  onGuestClick: () => void;
  onForgotPasswordClick: () => void;
}

export function AuthSocialButtons({
  onSignInClick,
  onSignUpClick,
  onGuestClick,
  onForgotPasswordClick,
}: AuthSocialButtonsProps) {
  const { signIn, isLoaded: signInLoaded } = useSignIn();
  const router = useRouter();

  const handleGoogleSignIn = async () => {
    if (!signInLoaded || !signIn) return;
    
    try {
      await signIn.authenticateWithRedirect({
        strategy: "oauth_google",
        redirectUrl: "/dashboard",
        redirectUrlComplete: "/dashboard",
      });
    } catch (error) {
      console.error("Google sign in error:", error);
    }
  };

  const handleFacebookSignIn = async () => {
    if (!signInLoaded || !signIn) return;
    
    try {
      await signIn.authenticateWithRedirect({
        strategy: "oauth_facebook",
        redirectUrl: "/dashboard",
        redirectUrlComplete: "/dashboard",
      });
    } catch (error) {
      console.error("Facebook sign in error:", error);
    }
  };

  return {
    handleGoogleSignIn,
    handleFacebookSignIn,
    handleEmailSignIn: onSignInClick,
    handleEmailSignUp: onSignUpClick,
    handleGuest: onGuestClick,
    handleForgotPassword: onForgotPasswordClick,
  };
}

// Hook to get auth state and methods
export function useAuthNavigation() {
  const { signIn, isLoaded: signInLoaded } = useSignIn();
  const router = useRouter();

  const signInWithGoogle = async () => {
    if (!signInLoaded || !signIn) return;
    try {
      await signIn.authenticateWithRedirect({
        strategy: "oauth_google",
        redirectUrl: "/dashboard",
        redirectUrlComplete: "/dashboard",
      });
    } catch (error) {
      console.error("Google sign in error:", error);
    }
  };

  const signInWithFacebook = async () => {
    if (!signInLoaded || !signIn) return;
    try {
      await signIn.authenticateWithRedirect({
        strategy: "oauth_facebook",
        redirectUrl: "/dashboard",
        redirectUrlComplete: "/dashboard",
      });
    } catch (error) {
      console.error("Facebook sign in error:", error);
    }
  };

  const signInWithEmail = () => {
    router.push("/sign-in");
  };

  const signUpWithEmail = () => {
    router.push("/sign-up");
  };

  const signInAsGuest = () => {
    router.push("/dashboard");
  };

  const goToForgotPassword = () => {
    router.push("/forgot-password");
  };

  return {
    signInWithGoogle,
    signInWithFacebook,
    signInWithEmail,
    signUpWithEmail,
    signInAsGuest,
    goToForgotPassword,
    isReady: signInLoaded,
  };
}

import React from 'react';
import { Comment, Screen, User } from '@/types';
import { IconRenderer } from '@/components/shared/IconRenderer';

interface CommentItemProps {
    comment: Comment;
    contributionId: string;
    listType: 'my' | 'saved' | 'moderation';
    depth?: number;
    replyTexts: { [key: string]: string };
    onReplyTextChange: (id: string, text: string) => void;
    onAddReply: (contributionId: string, parentId: string, listType: 'my' | 'saved' | 'moderation') => void;
    onCommentVote: (e: React.MouseEvent, contributionId: string, commentId: string, voteType: 'up' | 'down', listType: 'my' | 'saved' | 'moderation') => void;
    onToggleReply: (e: React.MouseEvent, contributionId: string, commentId: string, listType: 'my' | 'saved' | 'moderation') => void;
}

export const CommentItem: React.FC<CommentItemProps> = ({
    comment,
    contributionId,
    listType,
    depth = 0,
    replyTexts,
    onReplyTextChange,
    onAddReply,
    onCommentVote,
    onToggleReply
}) => {
    return (
        <div className={`flex gap-3 mt-4 ${depth > 0 ? 'ml-8 border-l-2 border-stone-100 dark:border-white/5 pl-4' : ''}`}>
            <img src={comment.avatar} alt={comment.author} className="w-8 h-8 rounded-full object-cover shrink-0" />
            <div className="flex-1 min-w-0">
                <div className="bg-stone-50 dark:bg-white/5 rounded-2xl rounded-tl-none p-3">
                    <div className="flex justify-between items-start">
                        <span className="font-bold text-sm text-stone-900 dark:text-white">{comment.author}</span>
                        <span className="text-xs text-stone-500 dark:text-text-muted">{comment.timestamp}</span>
                    </div>
                    <p className="text-sm text-stone-700 dark:text-text-main mt-1 break-words">{comment.text}</p>
                </div>
                <div className="flex items-center gap-4 mt-1 ml-1">
                    <button
                        onClick={(e) => onCommentVote(e, contributionId, comment.id, 'up', listType)}
                        className={`flex items-center gap-1 text-xs font-medium ${comment.userVote === 'up' ? 'text-primary' : 'text-stone-500 dark:text-text-muted hover:text-stone-900 dark:hover:text-white'}`}
                    >
                        <IconRenderer name="thumb_up" size={14} fill={comment.userVote === 'up'} />
                        {comment.likes > 0 && <span>{comment.likes}</span>}
                    </button>
                    <button
                        onClick={(e) => onCommentVote(e, contributionId, comment.id, 'down', listType)}
                        className={`flex items-center gap-1 text-xs font-medium ${comment.userVote === 'down' ? 'text-error' : 'text-stone-500 dark:text-text-muted hover:text-stone-900 dark:hover:text-white'}`}
                    >
                        <IconRenderer name="thumb_down" size={14} fill={comment.userVote === 'down'} />
                    </button>
                    <button
                        onClick={(e) => onToggleReply(e, contributionId, comment.id, listType)}
                        className="text-xs font-bold text-stone-500 dark:text-text-muted hover:text-stone-900 dark:hover:text-white"
                    >
                        Reply
                    </button>
                </div>
                {comment.isReplying && (
                    <div className="mt-3 flex gap-2 animate-in slide-in-from-top-2 duration-200">
                        <input
                            type="text"
                            value={replyTexts[comment.id] || ''}
                            onChange={(e) => onReplyTextChange(comment.id, e.target.value)}
                            placeholder="Write a reply..."
                            className="flex-1 bg-stone-100 dark:bg-black/20 border-none rounded-full px-4 py-2 text-sm text-stone-900 dark:text-white focus:ring-1 focus:ring-primary outline-none"
                            autoFocus
                            onKeyDown={(e) => e.key === 'Enter' && onAddReply(contributionId, comment.id, listType)}
                        />
                        <button
                            onClick={() => onAddReply(contributionId, comment.id, listType)}
                            disabled={!replyTexts[comment.id]?.trim()}
                            className="w-9 h-9 rounded-full bg-primary text-white flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed transition-all hover:bg-primary-hover shadow-sm"
                        >
                            <IconRenderer name="send" size={16} />
                        </button>
                    </div>
                )}
                {comment.replies && comment.replies.length > 0 && comment.replies.map(reply => (
                    <CommentItem
                        key={reply.id}
                        comment={reply}
                        contributionId={contributionId}
                        listType={listType}
                        depth={depth + 1}
                        replyTexts={replyTexts}
                        onReplyTextChange={onReplyTextChange}
                        onAddReply={onAddReply}
                        onCommentVote={onCommentVote}
                        onToggleReply={onToggleReply}
                    />
                ))}
            </div>
        </div>
    );
};

import React from 'react';
import { ContributionItem, User, Screen } from '@/types';
import { IconRenderer } from '@/components/shared/IconRenderer';
import { CommentItem } from './CommentItem';

interface ContributionCardProps {
    item: ContributionItem;
    listType: 'my' | 'saved' | 'moderation';
    navigate: (screen: Screen, params?: any) => void;
    onViewProfile: (user: User) => void;
    handleVote: (e: React.MouseEvent, id: string, voteType: 'up' | 'down', listType: 'my' | 'saved' | 'moderation') => void;
    toggleComments: (e: React.MouseEvent, id: string, listType: 'my' | 'saved' | 'moderation') => void;
    handleShareClick: (e: React.MouseEvent, item: ContributionItem) => void;
    inputTexts: { [key: string]: string };
    onInputChange: (id: string, text: string) => void;
    addComment: (id: string, listType: 'my' | 'saved' | 'moderation') => void;
    replyTexts: { [key: string]: string };
    onReplyTextChange: (id: string, text: string) => void;
    onAddReply: (contributionId: string, parentId: string, listType: 'my' | 'saved' | 'moderation') => void;
    onCommentVote: (e: React.MouseEvent, contributionId: string, commentId: string, voteType: 'up' | 'down', listType: 'my' | 'saved' | 'moderation') => void;
    onToggleReply: (e: React.MouseEvent, contributionId: string, commentId: string, listType: 'my' | 'saved' | 'moderation') => void;
    currentUserAvatar: string;
}

export const ContributionCard: React.FC<ContributionCardProps> = ({
    item,
    listType,
    navigate,
    onViewProfile,
    handleVote,
    toggleComments,
    handleShareClick,
    inputTexts,
    onInputChange,
    addComment,
    replyTexts,
    onReplyTextChange,
    onAddReply,
    onCommentVote,
    onToggleReply,
    currentUserAvatar
}) => {
    const handleNavigate = (item: ContributionItem) => {
        if (item.type === 'Story') navigate(Screen.STORY_DETAIL);
        if (item.type === 'Word') navigate(Screen.WORD_DETAIL);
        if (item.type === 'Proverb') navigate(Screen.PROVERB_DETAIL);
    };

    return (
        <div className="bg-white dark:bg-surface-dark rounded-2xl shadow-sm border border-stone-200 dark:border-white/5 overflow-hidden transition-all hover:shadow-md hover:border-primary/20 dark:hover:border-primary/30 group">
            <div className="p-4" onClick={() => handleNavigate(item)}>
