                            onClick={(e) => {
                                e.stopPropagation();
                                if (item.author) {
                                    onViewProfile({
                                        name: item.author.name,
                                        handle: item.author.handle || 'user',
                                        avatar: item.author.avatar,
                                        isGuest: false
                                    });
                                }
                            }}
