export const MediaPreview: React.FC<MediaPreviewProps> = ({ attachments, onRemove }) => {
    if (attachments.length === 0) return null;

    return (
        <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-primary text-lg">attachment</span>
                <h2 className="text-xs font-black uppercase tracking-[0.2em] text-foreground/80">Pending Attachments</h2>
            </div>

            <div className="grid grid-cols-1 gap-3">
                {attachments.map((att) => (
                    <Card key={att.id} className="p-3 bg-muted/20 border-border/50 flex items-center gap-4 group relative overflow-hidden">
                        <div className="h-12 w-12 rounded-xl bg-background flex items-center justify-center shrink-0 border border-border/50">
                            {att.type === 'image' ? (
                                <img src={att.previewUrl} alt="Preview" className="w-full h-full object-cover rounded-xl" />
                            ) : att.type === 'audio' ? (
                                <span className="material-symbols-outlined text-primary">audiotrack</span>
                            ) : (
                                <span className="material-symbols-outlined text-primary">videocam</span>
                            )}
                        </div>

                        <div className="flex-1 min-w-0">
                            <p className="text-xs font-bold truncate">{att.file.name}</p>
                            <p className="text-[10px] font-medium text-muted-foreground uppercase tracking-widest">
                                {(att.file.size / 1024).toFixed(1)} KB • {att.type}
                            </p>
                        </div>

                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 rounded-full text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
                            onClick={() => onRemove(att.id)}
                        >
                            <span className="material-symbols-outlined text-lg">close</span>
                        </Button>
                    </Card>
                ))}
            </div>
        </div>
    );
};

"use client";

import React from 'react';
import { LanguageHealth } from '@/types';

interface Props {
    languages: LanguageHealth[];
    selectedLanguage: string | null;
    onSelectLanguage: (code: string | null) => void;
}

export const LanguageHealthWidget: React.FC<Props> = ({
    languages,
    selectedLanguage,
    onSelectLanguage
}) => {
    const getHealthColor = (percent: number) => {
        if (percent >= 70) return 'bg-rasta-green';
        if (percent >= 40) return 'bg-rasta-gold';
        return 'bg-rasta-red';
    };

    const getHealthBorderColor = (percent: number) => {
        if (percent >= 70) return 'border-rasta-green/30';
        if (percent >= 40) return 'border-rasta-gold/30';
        return 'border-rasta-red/30';
    };

    const getHealthBgColor = (percent: number) => {
        if (percent >= 70) return 'bg-rasta-green/10';
        if (percent >= 40) return 'bg-rasta-gold/10';
        return 'bg-rasta-red/10';
    };

    return (
        <div className="w-full">
            <div className="flex items-center justify-between px-4 mb-3">
                <h3 className="text-xs font-black uppercase tracking-widest text-stone-500 dark:text-text-muted">
                    Your Languages Health
                </h3>
                {selectedLanguage && languages.length > 1 && (
                    <button
                        onClick={() => onSelectLanguage(null)}
                        className={`text-[10px] font-bold px-2 py-1 rounded-full transition-colors ${!selectedLanguage ? 'bg-primary text-white' : 'text-primary hover:bg-primary/10'}`}
                    >
                        Show All
                    </button>
                )}
            </div>

            <div className="flex gap-3 overflow-x-auto px-4 pb-4 no-scrollbar">
                {languages.map((lang) => (
                    <button
                        key={lang.id}
                        onClick={() => onSelectLanguage(lang.code)}
                        className={`flex-shrink-0 w-48 p-4 rounded-2xl border transition-all duration-300 text-left relative overflow-hidden group ${selectedLanguage === lang.code
                            ? 'border-primary ring-2 ring-primary/20 bg-white dark:bg-[#3d2b1f] shadow-lg scale-[1.02]'
                            : 'border-black/5 dark:border-white/5 bg-white/50 dark:bg-[#2a1d15] hover:border-primary/30'
                            }`}
                    >
                        <div className="flex justify-between items-start mb-3 relative z-10">
                            <div>
                                <h4 className="font-black text-stone-900 dark:text-white text-base leading-tight">
                                    {lang.name}
                                </h4>
                                <p className="text-[10px] uppercase font-bold text-stone-500 dark:text-text-muted/60 tracking-wider">
                                    {lang.code.toUpperCase()} • {lang.isUserModerator ? 'Moderator' : 'Contributor'}
                                </p>
                            </div>
                            {lang.pendingValidations > 0 && (
                                <div className="bg-rasta-red text-white text-[10px] font-black px-1.5 py-0.5 rounded-md animate-pulse shadow-sm">
                                    {lang.pendingValidations}
                                </div>
                            )}
                        </div>

                        <div className="space-y-1.5 relative z-10">
                            <div className="flex justify-between items-end">
                                <span className="text-[10px] font-bold text-stone-600 dark:text-text-muted">Stability</span>
                                <span className={`text-xs font-black ${lang.healthPercent >= 70 ? 'text-rasta-green' :
                                    lang.healthPercent >= 40 ? 'text-rasta-gold' : 'text-rasta-red'
                                    }`}>
                                    {lang.healthPercent}%
                                </span>
                            </div>
                            <div className="h-2 w-full bg-black/5 dark:bg-white/5 rounded-full overflow-hidden">
                                <div
                                    className={`h-full rounded-full transition-all duration-1000 ease-out ${getHealthColor(lang.healthPercent)}`}
                                    style={{ width: `${lang.healthPercent}%` }}
                                />
                            </div>
                        </div>

                        <p className="text-[10px] font-medium text-stone-500 dark:text-text-muted/60 mt-3 relative z-10">
                            {lang.validatedContributions} validated / {lang.targetContributions} target
                        </p>

                        {/* Decorative background element */}
                        <div className={`absolute top-0 right-0 w-24 h-24 rounded-full -mr-8 -mt-8 opacity-20 blur-2xl group-hover:scale-125 transition-transform duration-700 ${getHealthBgColor(lang.healthPercent)}`}></div>
                    </button>
                ))}

                {/* Empty space at the end for padding */}
                <div className="flex-shrink-0 w-1"></div>
            </div>
        </div>
    );
};

"use client";

import React, { useState } from 'react';
import { X, Flag, AlertTriangle, Check } from 'lucide-react';

interface Props {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (reason: string, details?: string) => void;
}

const REASONS = [
    { id: 'inaccurate', label: 'Inaccurate Translation', desc: 'The translation does not match the original text.' },
    { id: 'low-quality', label: 'Low Linguistic Quality', desc: 'Grammar or spelling is poor.' },
    { id: 'spam', label: 'Spam / Commercial', desc: 'Post is promotional or repetitive.' },
    { id: 'duplicate', label: 'Duplicate Content', desc: 'This contribution already exists.' },
    { id: 'inappropriate', label: 'Inappropriate Content', desc: 'Violates community guidelines.' },
    { id: 'other', label: 'Other / Custom Reason', desc: 'Something else is wrong.' },
];

export const ReportModal: React.FC<Props> = ({
    isOpen,
    onClose,
    onSubmit
}) => {
    const [selectedReason, setSelectedReason] = useState<string | null>(null);
    const [details, setDetails] = useState('');

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white dark:bg-[#32241a] w-full max-w-md rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
                <div className="p-6">
                    <div className="flex justify-between items-center mb-6">
                        <div className="flex items-center gap-3">
                            <div className="size-10 rounded-2xl bg-rasta-red flex items-center justify-center text-white shadow-lg shadow-rasta-red/20">
                                <Flag className="size-5" />
                            </div>
                            <div>
                                <h3 className="text-xl font-black text-stone-900 dark:text-white">Flag Content</h3>
                                <p className="text-xs font-bold text-stone-500 dark:text-text-muted">Report low quality or issues</p>
                            </div>
                        </div>
                        <button
                            onClick={onClose}
                            className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/5 transition-colors"
                        >
                            <X className="size-6 text-stone-400" />
                        </button>
                    </div>

                    <div className="space-y-3 mb-6">
                        {REASONS.map((reason) => (
                            <button
                                key={reason.id}
                                onClick={() => setSelectedReason(reason.id)}
                                className={`w-full p-3 rounded-2xl border text-left transition-all ${selectedReason === reason.id
                                        ? 'border-rasta-red bg-rasta-red/5 ring-1 ring-rasta-red/20'
                                        : 'border-black/5 dark:border-white/5 bg-black/5 dark:bg-white/5 hover:bg-black/10'
                                    }`}
                            >
                                <div className="flex items-center justify-between mb-0.5">
                                    <span className={`text-sm font-black ${selectedReason === reason.id ? 'text-rasta-red' : 'text-stone-900 dark:text-white'}`}>
                                        {reason.label}
                                    </span>
                                    {selectedReason === reason.id && <div className="size-2 rounded-full bg-rasta-red" />}
                                </div>
                                <p className="text-[10px] font-medium text-stone-500 dark:text-text-muted">
                                    {reason.desc}
                                </p>
                            </button>
                        ))}
                    </div>

                    {selectedReason === 'other' && (
                        <textarea
                            value={details}
                            onChange={(e) => setDetails(e.target.value)}
                            placeholder="Please provide more details..."
                            className="w-full h-24 mb-4 bg-black/5 dark:bg-black/40 border-none rounded-2xl p-4 text-sm text-stone-900 dark:text-white placeholder:text-stone-400 dark:placeholder:text-text-muted/40 focus:ring-2 focus:ring-rasta-red transition-all resize-none outline-none"
                        />
                    )}

                    <div className="flex gap-3">
                        <button
                            onClick={onClose}
                            className="flex-1 py-3 text-sm font-black text-stone-500 hover:bg-black/5 dark:hover:bg-white/5 rounded-2xl transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            disabled={!selectedReason || (selectedReason === 'other' && !details.trim())}
                            onClick={() => {
                                const reasonLabel = REASONS.find(r => r.id === selectedReason)?.label || 'Other';
                                onSubmit(reasonLabel, details);
                                setSelectedReason(null);
                                setDetails('');
                            }}
                            className="flex-1 py-3 bg-rasta-red text-white text-sm font-black rounded-2xl shadow-lg shadow-rasta-red/20 flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                        >
                            <AlertTriangle className="size-4" />
                            Flag Content
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

"use client";

import React, { useState } from 'react';
import { ValidationItem, Screen } from '@/types';
import {

    ShieldAlert,
    MessageSquare,
    CheckCircle,
    Flag,
    ChevronDown,
    ChevronUp,
    ThumbsUp,
    ThumbsDown,
    Clock,
    ExternalLink,
    BookOpen,
    Languages,
    Quote,
    Music,
    FileText,
    User
} from 'lucide-react';

interface Props {
    item: ValidationItem;
    currentUserId: string;
    isUserModerator: boolean;
    onApprove: (id: string) => void;
    onCritique: (id: string) => void;
    onReport: (id: string) => void;
    onViewProfile: (handle: string) => void;
    onNavigate: (screen: Screen) => void;
    onVote: (id: string, direction: 'up' | 'down' | null) => void;
}

export const ValidationCard: React.FC<Props> = ({
    item,
    currentUserId,
    isUserModerator,
    onApprove,
    onCritique,
    onReport,
    onViewProfile,
    onNavigate,
    onVote
}) => {

    const [showHistory, setShowHistory] = useState(false);
    const isAuthor = item.author.id === currentUserId;

    // Local state for optimistic UI updates on voting
    const [localVote, setLocalVote] = useState<'up' | 'down' | null>(item.sentiment.userVote || null);
    const [localVotes, setLocalVotes] = useState({
        up: item.sentiment.upvotes,
        down: item.sentiment.downvotes
    });

    const handleVote = (direction: 'up' | 'down') => {
        if (localVote === direction) {
            // Toggle off
            setLocalVote(null);
            setLocalVotes(prev => ({
                ...prev,
                [direction]: prev[direction] - 1
            }));
            onVote(item.id, null);
        } else {
            // Switch vote
            setLocalVotes(prev => ({
                up: direction === 'up' ? prev.up + 1 : (localVote === 'up' ? prev.up - 1 : prev.up),
                down: direction === 'down' ? prev.down + 1 : (localVote === 'down' ? prev.down - 1 : prev.down)
            }));
            setLocalVote(direction);
            onVote(item.id, direction);
        }
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'Story': return <BookOpen className="size-4" />;
            case 'Word': return <Languages className="size-4" />;
            case 'Proverb': return <Quote className="size-4" />;
            case 'Song': return <Music className="size-4" />;
            default: return <FileText className="size-4" />;
        }
    };

    const statusColors = {
        pending: 'text-rasta-gold bg-rasta-gold/10',
        approved: 'text-rasta-green bg-rasta-green/10',
        needs_revision: 'text-rasta-red bg-rasta-red/10',
        rejected: 'text-rasta-red bg-rasta-red/10',
    };

    return (
        <div className={`bg-white dark:bg-[#32241a] rounded-2xl p-5 shadow-sm space-y-4 border border-black/5 dark:border-white/5 transition-all overflow-hidden ${isAuthor ? 'ring-1 ring-primary/20 bg-primary/5' : ''}`}>
            {/* Header */}
            <div className="flex justify-between items-start">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-black/5 dark:bg-white/5 flex items-center justify-center text-stone-600 dark:text-sand-beige">
                        {getTypeIcon(item.type)}
                    </div>
                    <div>
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-black uppercase tracking-widest text-primary">
                                {item.type}
                            </span>
                            <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-black/5 dark:bg-white/10 text-stone-500 dark:text-text-muted">
                                {item.language}
                            </span>
                        </div>
                        <div className="flex items-center gap-1 mt-0.5">
                            <span className="text-sm font-bold text-stone-900 dark:text-white">
                                {item.content.original.length > 30 ? item.content.original.substring(0, 30) + '...' : item.content.original}
                            </span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-2">
                    <span className={`text-[10px] font-black uppercase tracking-wider px-2 py-1 rounded-full ${statusColors[item.status]}`}>
                        {item.status.replace('_', ' ')}
                    </span>
                    <span className="text-[10px] font-bold text-stone-400 dark:text-text-muted/60 flex items-center gap-1">
                        <Clock className="size-3" />
                        {item.timestamp}
                    </span>
                </div>
            </div>

            {/* Content */}
            <div className="space-y-3">
                <div className="p-4 bg-black/5 dark:bg-black/20 rounded-xl relative group">
                    <p className="text-base font-medium text-stone-900 dark:text-white leading-relaxed whitespace-pre-wrap">
                        {item.content.original}
                    </p>
                    {item.content.translation && (
                        <div className="mt-3 pt-3 border-t border-black/5 dark:border-white/5">
                            <p className="text-sm text-stone-600 dark:text-sand-beige italic">
                                {item.content.translation}
                            </p>
                        </div>
                    )}
                    {item.content.meaning && (
                        <p className="mt-2 text-xs text-stone-500 dark:text-text-muted">
                            <span className="font-bold">Meaning: </span>{item.content.meaning}
                        </p>
                    )}
                </div>

                {/* Sentiment & Author */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <button
                            onClick={() => handleVote('up')}
                            className={`flex items-center gap-1.5 transition-colors ${localVote === 'up' ? 'text-primary' : 'text-stone-400 dark:text-text-muted hover:text-primary'}`}
                        >
                            <ThumbsUp className={`size-4 ${localVote === 'up' ? 'fill-current' : ''}`} />
                            <span className={`text-xs font-bold ${localVote === 'up' ? 'text-primary' : 'text-stone-600 dark:text-text-muted'}`}>
                                {localVotes.up}
                            </span>
                        </button>

                        <button
                            onClick={() => handleVote('down')}
                            className={`flex items-center gap-1.5 transition-colors ${localVote === 'down' ? 'text-rasta-red' : 'text-stone-400 dark:text-text-muted hover:text-rasta-red'}`}
                        >
                            <ThumbsDown className={`size-4 ${localVote === 'down' ? 'fill-current' : ''}`} />
                            <span className={`text-xs font-bold ${localVote === 'down' ? 'text-rasta-red' : 'text-stone-600 dark:text-text-muted'}`}>
                                {localVotes.down}
                            </span>
                        </button>

                        <div className="flex items-center gap-1.5 px-2 py-1 bg-rasta-green/10 rounded-lg">
                            <CheckCircle className="size-3 text-rasta-green" />
                            <span className="text-xs font-black text-rasta-green">
                                {item.reviews.filter(r => r.action === 'approved').length}
                            </span>
                        </div>
                    </div>

                    <button
                        onClick={() => onViewProfile(item.author.handle)}
                        className="flex items-center gap-2 group"
                    >
                        <div className="text-right">
                            <p className="text-xs font-black text-stone-900 dark:text-white group-hover:text-primary transition-colors">
                                {isAuthor ? 'You' : item.author.name}
                            </p>
                            <p className="text-[10px] font-bold text-stone-500 dark:text-text-muted/60">
                                {isAuthor ? 'Your post' : item.author.handle}
                            </p>
                        </div>
                        <img
                            src={item.author.avatar}
                            alt={item.author.name}
                            className="size-8 rounded-full border border-black/5 dark:border-white/10"
                        />
                    </button>
                </div>
            </div>



            {/* Review History / Avatars */}
            <div className="pt-2">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="flex -space-x-2">
                            {item.reviews.length > 0 ? (
                                item.reviews.slice(0, 3).map((review, i) => (
                                    <img
                                        key={i}
                                        src={review.moderator.avatar}
                                        alt={review.moderator.name}
                                        className="size-6 rounded-full border-2 border-white dark:border-[#32241a] shadow-sm hover:z-10 transition-transform hover:scale-110 cursor-pointer"
                                        title={review.moderator.name}
                                    />
                                ))
                            ) : (
                                <div className="size-6 rounded-full bg-black/5 dark:bg-white/5 flex items-center justify-center border-2 border-white dark:border-[#32241a]">
                                    <User className="size-3 text-stone-400" />
                                </div>
                            )}
                            {item.reviews.length > 3 && (
                                <div className="size-6 rounded-full bg-stone-100 dark:bg-white/10 flex items-center justify-center text-[10px] font-black text-stone-500 dark:text-text-muted border-2 border-white dark:border-[#32241a]">
                                    +{item.reviews.length - 3}
                                </div>
                            )}
                        </div>
                        <p className="text-[10px] font-bold text-stone-500 dark:text-text-muted/60">
                            {item.reviews.length > 0 ? `${item.reviews.length} reviews so far` : 'Waiting for review'}
                        </p>
                    </div>

                    <button
                        disabled={item.reviews.length === 0}
                        onClick={() => setShowHistory(!showHistory)}
                        className="text-[10px] font-black text-primary hover:underline disabled:opacity-30 flex items-center gap-1"
                    >
                        {showHistory ? 'Hide History' : 'View History'}
                        <ChevronDown className={`size-3 transition-transform ${showHistory ? 'rotate-180' : ''}`} />
                    </button>
                </div>

                {showHistory && item.reviews.length > 0 && (
                    <div className="mt-3 space-y-2 pt-3 border-t border-black/5 dark:border-white/5 animate-in fade-in duration-300">
                        {item.reviews.map((review, i) => (
                            <div key={i} className="flex gap-3">
                                <img src={review.moderator.avatar} alt={review.moderator.name} className="size-8 rounded-full h-fit mt-1" />
                                <div className="flex-1">
                                    <div className="flex justify-between items-center mb-1">
                                        <p className="text-xs font-black text-stone-900 dark:text-white">{review.moderator.name}</p>
                                        <span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded-full ${review.action === 'approved' ? 'text-rasta-green bg-rasta-green/10' :
                                            review.action === 'critiqued' ? 'text-rasta-gold bg-rasta-gold/10' : 'text-rasta-red bg-rasta-red/10'
                                            }`}>
                                            {review.action}
                                        </span>
                                    </div>
                                    {review.comment && (
                                        <p className="text-[11px] text-stone-600 dark:text-text-muted leading-relaxed italic bg-black/5 dark:bg-black/20 p-2 rounded-lg">
                                            "{review.comment}"
                                        </p>
                                    )}
                                    <p className="text-[8px] text-stone-400 dark:text-text-muted/40 mt-1">
                                        {new Date(review.timestamp).toLocaleDateString()}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Action Bar */}
            <div className="pt-4 border-t border-black/5 dark:border-white/10 flex items-center justify-between">
                {isAuthor ? (
                    <div className="flex flex-1 items-center justify-center p-2 bg-black/5 dark:bg-white/5 rounded-xl border border-dashed border-stone-200 dark:border-white/10">
                        <p className="text-[10px] font-bold text-stone-400 dark:text-text-muted uppercase tracking-widest flex items-center gap-2">
                            <ShieldAlert className="size-3" />
                            Progress View Only (Author)
                        </p>
                    </div>
                ) : (
                    <>
                        {item.reviews.some(r => r.moderator.id === currentUserId) ? (
                            <div className="flex-1 flex items-center justify-center p-2 bg-black/5 dark:bg-white/5 rounded-xl border border-stone-200 dark:border-white/10">
                                <p className="text-[10px] font-bold text-stone-500 dark:text-text-muted uppercase tracking-widest flex items-center gap-2">
                                    <CheckCircle className="size-3" />
                                    You have reviewed this
                                </p>
                            </div>
                        ) : (
                            <>
                                <div className="flex gap-2 flex-1">
                                    <button
                                        disabled={!isUserModerator}
                                        onClick={() => onApprove(item.id)}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl bg-rasta-green text-white font-black text-xs shadow-lg shadow-rasta-green/20 active:scale-95 transition-all hover:bg-rasta-green/90 disabled:opacity-50 disabled:grayscale"
                                    >
                                        <CheckCircle className="size-4" />
                                        Approve
                                    </button>
                                    <button
                                        disabled={!isUserModerator}
                                        onClick={() => onCritique(item.id)}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl bg-rasta-gold text-stone-900 font-black text-xs shadow-lg shadow-rasta-gold/20 active:scale-95 transition-all hover:bg-rasta-gold/90 disabled:opacity-50 disabled:grayscale"
                                    >
                                        <MessageSquare className="size-4" />
                                        Critique
                                    </button>
                                </div>
                                <button
                                    disabled={!isUserModerator}
                                    onClick={() => onReport(item.id)}
                                    className="ml-2 p-2.5 rounded-xl bg-rasta-red/10 text-rasta-red hover:bg-rasta-red/20 transition-colors disabled:opacity-30 disabled:grayscale"
                                    title="Report/Reject Quality"
                                >
                                    <Flag className="size-4" />
                                </button>
                            </>
                        )}
                    </>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Screen, ChallengeType, InputType, ChallengeInputField } from '@/types';
import { useUser } from '@/app/MockProviders';

interface Props {
  navigate: (screen: Screen, params?: any) => void;
  goBack: () => void;
}

const AddChallengeScreen: React.FC<Props> = ({ navigate, goBack }) => {
  const { addChallenge } = useUser();
  const [step, setStep] = useState(1);
  const [selectedType, setSelectedType] = useState<ChallengeType | null>(null);
  const [formData, setFormData] = useState({
    title: '',
    goalCount: 50,
    deadline: '7 Days',
    invitees: [] as string[],
    goalDescription: '',
    inputSchema: [
      { id: '1', type: 'AUDIO', label: 'Audio Recording', required: true }
    ] as ChallengeInputField[]
  });
  const [customMission, setCustomMission] = useState('');

  // Squad State
  const [squad, setSquad] = useState([
    { name: 'Wanjiku M.', avatar: 'WM', selected: true },
    { name: 'Ochieng J.', avatar: 'OJ', selected: false },
    { name: 'Kamau K.', avatar: 'KK', selected: true },
    { name: 'Aisha S.', avatar: 'AS', selected: false },
  ]);

  const [suggestions, setSuggestions] = useState([
    { name: 'Dr. Ali', avatar: 'DA', role: 'Linguist' },
    { name: 'Mama Z.', avatar: 'MZ', role: 'Elder' },
    { name: 'Kevo', avatar: 'K', role: 'Historian' },
    { name: 'Sarah', avatar: 'S', role: 'Teacher' },
  ]);

  const handleAddToSquad = (user: typeof suggestions[0]) => {
    setSquad([...squad, { ...user, selected: true }]);
    setSuggestions(suggestions.filter(s => s.name !== user.name));
  };

  const handleNext = () => setStep(s => s + 1);
  const handleBack = () => setStep(s => s - 1);

  const PROJECT_TYPES: { type: ChallengeType; label: string; icon: string; desc: string; color: string }[] = [
    { type: 'ACCENT', label: 'Accent Preservation', icon: 'mic', desc: 'Collect audio recordings of local accents.', color: 'bg-red-500' },
    { type: 'DIALECT', label: 'Dialect Mapping', icon: 'map', desc: 'Pin specific dialect variations on a map.', color: 'bg-green-600' },
    { type: 'ALPHABET', label: 'Alphabet Creation', icon: 'border_color', desc: 'Design or document scripts/symbols.', color: 'bg-blue-600' },
    { type: 'TOTEM', label: 'Totem Registry', icon: 'photo_camera', desc: 'Archive photos and histories of totems.', color: 'bg-amber-600' },
  ];

  const handleTypeSelect = (type: ChallengeType) => {
    setSelectedType(type);
    handleNext();
  };

  const handleCustomTypeSelect = () => {
    if (!customMission.trim()) return;
    setSelectedType('CUSTOM');
    // Pre-fill the title with the custom mission name
    setFormData(prev => ({ ...prev, title: customMission }));
    handleNext();
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#FAF9F6] dark:bg-[#2b1e19] text-stone-900 dark:text-white transition-colors duration-300 font-display">
      {/* Header */}
      <header className="flex items-center p-4 sticky top-0 bg-[#FAF9F6]/90 dark:bg-[#2b1e19]/90 backdrop-blur-md z-20">
        <button onClick={step === 1 ? goBack : handleBack} className="p-2 -ml-2 text-stone-500 hover:text-[#cf6317] transition-colors">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <div className="flex-1 text-center">
          <h1 className="text-lg font-bold">Start a Movement</h1>
          <div className="flex justify-center gap-1 mt-1">
            {[1, 2, 3].map(i => (
              <div key={i} className={`h-1 w-8 rounded-full transition-colors ${step >= i ? 'bg-[#cf6317]' : 'bg-stone-200 dark:bg-white/10'}`} />
            ))}
          </div>
        </div>
        <div className="w-10"></div>
      </header>

      <main className="flex-1 p-6 pb-32 max-w-lg mx-auto w-full animate-in fade-in slide-in-from-bottom-4 duration-500">

        {/* STEP 1: CHOOSE TYPE */}
        {step === 1 && (
          <div className="space-y-6">
            <div className="text-center space-y-2 mb-8">
              <h2 className="text-2xl font-extrabold text-stone-900 dark:text-white">Choose Your Mission</h2>
              <p className="text-stone-500 dark:text-[#A8A29E]">What part of heritage needs saving today?</p>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {PROJECT_TYPES.map((t) => (
                <button
                  key={t.type}
                  onClick={() => handleTypeSelect(t.type)}
                  className="relative group overflow-hidden bg-white dark:bg-[#42342b] border border-stone-200 dark:border-white/5 p-6 rounded-2xl flex items-center gap-5 hover:border-[#cf6317] hover:shadow-lg transition-all text-left"
                >
                  <div className={`w-14 h-14 rounded-full ${t.color} bg-opacity-10 flex items-center justify-center group-hover:scale-110 transition-transform`}>
                    <span className={`material-symbols-outlined text-2xl ${t.color.replace('bg-', 'text-')}`}>{t.icon}</span>
                  </div>
                  <div className="flex-1">
                    <h3 className="font-bold text-lg text-stone-900 dark:text-white group-hover:text-[#cf6317] transition-colors">{t.label}</h3>
                    <p className="text-sm text-stone-500 dark:text-[#A8A29E] leading-relaxed">{t.desc}</p>
                  </div>
                  <span className="material-symbols-outlined text-stone-300 group-hover:text-[#cf6317] transition-colors">chevron_right</span>
                </button>
              ))}
            </div>

            {/* Custom Mission Input */}
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-stone-200 dark:border-white/10" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="bg-[#FAF9F6] dark:bg-[#2b1e19] px-2 text-stone-500">Or create your own</span>
              </div>
            </div>

            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Name your mission (e.g. Digital Museum)"
                className="flex-1 bg-white dark:bg-[#42342b] border border-stone-200 dark:border-white/10 rounded-xl p-4 text-stone-900 dark:text-white focus:border-[#cf6317] outline-none transition-colors"
                value={customMission}
                onChange={(e) => setCustomMission(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && customMission.trim()) {
                    handleCustomTypeSelect();
                  }
                }}
              />
              <button
                onClick={handleCustomTypeSelect}
                disabled={!customMission.trim()}
                className="bg-stone-900 dark:bg-white text-white dark:text-stone-900 rounded-xl px-4 aspect-square flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:opacity-90 transition-opacity"
              >
                <span className="material-symbols-outlined">arrow_forward</span>
              </button>
            </div>
          </div>
        )}

        {/* STEP 2: DEFINE GOALS */}
        {
          step === 2 && (
            <div className="space-y-8">
              <div className="text-center space-y-2 mb-4">
                <h2 className="text-2xl font-extrabold text-stone-900 dark:text-white">Define Success</h2>
                <p className="text-stone-500 dark:text-[#A8A29E]">Set a target to motivate the community.</p>
              </div>


              <div className="space-y-6">
                {/* Goal Description */}
                <div>
                  <label className="block text-sm font-bold text-stone-700 dark:text-stone-300 mb-2">Goal Description</label>
                  <textarea
                    value={formData.goalDescription}
                    onChange={(e) => setFormData({ ...formData, goalDescription: e.target.value })}
                    placeholder="Describe what success looks like (e.g. We need 50 recordings of the elders in the village...)"
                    className="w-full bg-white dark:bg-[#42342b] border-2 border-stone-200 dark:border-white/10 rounded-xl p-4 font-medium text-lg text-stone-900 dark:text-white placeholder-stone-300 focus:border-[#cf6317] outline-none transition-colors min-h-[120px] resize-y"
                  />
                </div>

                {/* Submission Inputs Builder */}
                <div>
                  <div className="flex items-center justify-between mb-4">
                    <label className="block text-sm font-bold text-stone-700 dark:text-stone-300">Submission Requirements</label>
                    <span className="text-xs font-bold text-stone-400 uppercase tracking-widest">What creators submit</span>
                  </div>

                  <div className="space-y-3">
                    {formData.inputSchema.map((input, index) => (
                      <div key={input.id} className="bg-white dark:bg-[#42342b] border border-stone-200 dark:border-white/10 p-4 rounded-xl flex items-center gap-4 group">
                        <div className="w-10 h-10 rounded-full bg-stone-100 dark:bg-white/5 flex items-center justify-center text-stone-500">
                          <span className="material-symbols-outlined">
                            {input.type === 'AUDIO' ? 'mic' :
                              input.type === 'VIDEO' ? 'videocam' :
                                input.type === 'IMAGE' ? 'image' :
                                  input.type === 'LOCATION' ? 'location_on' : 'text_fields'}
                          </span>
                        </div>
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <input
                              value={input.label}
                              onChange={(e) => {
                                const newSchema = [...formData.inputSchema];
                                newSchema[index].label = e.target.value;
                                setFormData({ ...formData, inputSchema: newSchema });
                              }}
                              className="font-bold text-stone-900 dark:text-white bg-transparent outline-none focus:underline decoration-[#cf6317]"
                            />
                            <span className="material-symbols-outlined text-stone-300 text-sm cursor-help" title="Click to rename">edit</span>
                          </div>
                          <div className="text-xs text-stone-400 font-medium flex gap-2">
                            <span>{input.type}</span>
                            <span>•</span>
                            <button
                              onClick={() => {
                                const newSchema = [...formData.inputSchema];
                                newSchema[index].required = !newSchema[index].required;
                                setFormData({ ...formData, inputSchema: newSchema });
                              }}
                              className={`${input.required ? 'text-[#cf6317]' : 'text-stone-300'} font-bold hover:underline`}
                            >
                              {input.required ? 'Required' : 'Optional'}
                            </button>
                          </div>
                        </div>
                        <button
                          onClick={() => {
                            const newSchema = formData.inputSchema.filter((_, i) => i !== index);
                            setFormData({ ...formData, inputSchema: newSchema });
                          }}
                          className="p-2 text-stone-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-colors"
                        >
                          <span className="material-symbols-outlined">delete</span>
                        </button>
                      </div>
                    ))}

                    {/* Add Field Button */}
                    <div className="flex gap-2 flex-wrap">
                      {(['TEXT', 'AUDIO', 'VIDEO', 'IMAGE', 'LOCATION'] as InputType[]).map(type => (
                        <button
                          key={type}
                          onClick={() => {
                            const newField: ChallengeInputField = {
                              id: Math.random().toString(36).substr(2, 9),
                              type,
                              label: type === 'TEXT' ? 'Description' :
                                type === 'AUDIO' ? 'Recording' :
                                  type === 'VIDEO' ? 'Video Clip' :
                                    type === 'IMAGE' ? 'Photo' : 'Location',
                              required: true
                            };
                            setFormData({ ...formData, inputSchema: [...formData.inputSchema, newField] });
                          }}
                          className="px-3 py-2 rounded-lg border border-dashed border-stone-300 dark:border-white/20 text-xs font-bold text-stone-500 hover:bg-stone-50 dark:hover:bg-white/5 hover:text-[#cf6317] hover:border-[#cf6317] transition-all flex items-center gap-1"
                        >
                          <span className="material-symbols-outlined text-[16px]">add</span>
                          {type}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )
        }

        {/* STEP 3: INVITE SQUAD */}
        {
          step === 3 && (
            <div className="space-y-6">
              <div className="text-center space-y-2 mb-8">
                <h2 className="text-2xl font-extrabold text-stone-900 dark:text-white">Assemble Your Squad</h2>
                <p className="text-stone-500 dark:text-[#A8A29E]">Who are the best experts for this task?</p>
              </div>

              <div className="bg-white dark:bg-[#42342b] border border-stone-200 dark:border-white/5 rounded-2xl overflow-hidden divide-y divide-stone-100 dark:divide-white/5">
                {squad.map((user, idx) => (
                  <div
                    key={idx}
                    onClick={() => {
                      const newSquad = [...squad];
                      newSquad[idx].selected = !newSquad[idx].selected;
                      setSquad(newSquad);
                    }}
                    className="p-4 flex items-center justify-between hover:bg-stone-50 dark:hover:bg-black/20 cursor-pointer"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-stone-200 dark:bg-white/10 flex items-center justify-center font-bold text-stone-600 dark:text-stone-400">
                        {user.avatar}
                      </div>
                      <span className="font-bold text-stone-700 dark:text-white">{user.name}</span>
                    </div>
                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${user.selected ? 'bg-[#cf6317] border-[#cf6317]' : 'border-stone-300 dark:border-white/20'}`}>
                      {user.selected && <span className="material-symbols-outlined text-white text-sm">check</span>}
                    </div>
                  </div>
                ))}
              </div>

              <button className="w-full py-4 rounded-xl border-2 border-dashed border-stone-300 dark:border-white/20 text-stone-500 dark:text-stone-400 font-bold hover:bg-stone-50 dark:hover:bg-white/5 transition-colors">
                + Copy Invite Link
              </button>

              {/* Suggestions Section */}
              {suggestions.length > 0 && (
                <div className="pt-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
                  <div className="flex items-center justify-between mb-3 px-1">
                    <h3 className="font-bold text-stone-700 dark:text-stone-300">Suggested Experts</h3>
                    <span className="text-xs text-stone-400">Based on your mission</span>
                  </div>

                  <div className="flex gap-3 overflow-x-auto pb-4 snap-x">
                    {suggestions.map((user, idx) => (
                      <div
                        key={idx}
                        className="snap-center shrink-0 w-32 bg-white dark:bg-[#42342b] border border-stone-200 dark:border-white/5 rounded-xl p-3 flex flex-col items-center gap-2 text-center shadow-sm"
                      >
                        <div className="w-12 h-12 rounded-full bg-orange-100 dark:bg-orange-900/20 flex items-center justify-center font-bold text-[#cf6317]">
                          {user.avatar}
                        </div>
                        <div>
                          <div className="font-bold text-sm text-stone-900 dark:text-white truncate w-full">{user.name}</div>
                          <div className="text-xs text-stone-400">{user.role}</div>
                        </div>
                        <button
                          onClick={() => handleAddToSquad(user)}
                          className="mt-1 w-full py-1.5 bg-stone-900 dark:bg-white text-white dark:text-stone-900 text-xs font-bold rounded-lg hover:opacity-90 transition-opacity"
                        >
                          Add +
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )
        }

      </main>

      {/* Footer Actions */}
      <footer className="sticky bottom-0 z-20 bg-white/90 dark:bg-[#2b1e19]/90 backdrop-blur-md p-4 border-t border-stone-200 dark:border-white/5 transition-colors">
        {step === 1 ? (
          <div className="text-center text-xs text-stone-400 font-bold uppercase tracking-widest pb-2">Select a type to proceed</div>
        ) : (
          <button
            onClick={step === 3 ? () => {
              const newChallenge = {
                id: `new-${Date.now()}`,
                title: formData.title || 'New Project',
                description: formData.goalDescription || `A collaborative ${selectedType?.toLowerCase()} project.`,
                type: selectedType!,
                goalCount: 0,
                goalDescription: formData.goalDescription,
                inputSchema: formData.inputSchema,
                currentCount: 0,
                goalMetric: 'Entries',
                image: 'https://images.unsplash.com/photo-1544985335-7c2a74c10648?auto=format&fit=crop&q=80&w=2000'
              };
              addChallenge(newChallenge);
              navigate(Screen.CONTRIBUTIONS, { tab: 'Challenges' }); // Navigate to Contributions with Challenges tab
            } : handleNext}
            className="w-full bg-[#cf6317] hover:bg-[#b05210] text-white font-bold py-4 rounded-xl shadow-lg active:scale-[0.98] transition-all flex items-center justify-center gap-2"
          >
            {step === 3 ? 'Launch Project 🚀' : 'Continue'}
          </button>
        )}
      </footer>
    </div >
  );
};

