const MESSAGES_PER_PAGE = 20;

const ChatScreen: React.FC<Props> = ({ user, navigate, unreadCount = 0, notificationCounts, activeConversation, onNewChat, onSaveChat, isDarkMode, toggleTheme }) => {
  const translate = useAction(api.translate.translateText);
  const sendMessageAction = useAction(api.chat.sendMessage);
  const transcribeAudio = useAction(api.asr.transcribeAudio);
  const synthesizeSpeech = useAction(api.tts.synthesizeSpeech);
  const diagnoseServices = useAction(api.diagnostic.diagnoseServices);

  const [isNavOpen, setIsNavOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  // Language State - Default to Swahili so translations are enabled by default
  // LANGUAGES order: Kenyan languages first
  const [selectedLanguage, setSelectedLanguage] = useState<Language>(
    LANGUAGES.find(l => l.code === 'sw') || LANGUAGES[0]
  );
  // Replaced with internal state in LanguageSelector, but we keep this for controlled if needed,
  // or simply use it to toggle. Actually, we can remove isLanguageDropdownOpen if we use the component properly.
  // But wait, the component needs an 'open' prop if we want to control it, or we rely on its internal state.
  // The existing code has two places using it. It's better to keep it controlled or separate.
  // We'll use separate states for the two instances or just let them manage themselves if possible?
  // Language Selector now manages its own open state internally

  // ASR State
  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // TTS State
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [isSynthesizing, setIsSynthesizing] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Attachment State
  const [isAttachmentMenuOpen, setIsAttachmentMenuOpen] = useState(false);

  // Feedback State
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');


  // Translation Visibility State
  const [expandedTranslations, setExpandedTranslations] = useState<{ [key: string]: boolean }>({});

  // Copy State
  const [copiedMessageId, setCopiedMessageId] = useState<string | null>(null);

  // Diagnostic State
  const [isRunningDiagnostics, setIsRunningDiagnostics] = useState(false);
  const [diagnosticResults, setDiagnosticResults] = useState<Array<{service: string, status: string, message: string, details?: string}>>([]);
  const [showDiagnostics, setShowDiagnostics] = useState(false);

  // Run diagnostics handler
  const runDiagnostics = async () => {
    setIsRunningDiagnostics(true);
    setShowDiagnostics(true);
    try {
      const results = await diagnoseServices();
      setDiagnosticResults(results);
    } catch (error) {
      console.error("Diagnostics failed:", error);
      setDiagnosticResults([{ service: "Error", status: "error", message: "Failed to run diagnostics", details: String(error) }]);
    }
    setIsRunningDiagnostics(false);
  };

  const handleCopy = (text: string, id: string) => {
    copyToClipboard(text);
    setCopiedMessageId(id);
    setTimeout(() => {
      setCopiedMessageId(null);
    }, 2000);
  };

  // Welcome Mode - true when no user messages exist (Google-style centered layout)
  const isWelcomeMode = !messages.some(m => m.sender === 'user');

  // Scroll Header Logic
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [showScrollToBottom, setShowScrollToBottom] = useState(false);
  const [hasNewMessage, setHasNewMessage] = useState(false);
  const [visibleCount, setVisibleCount] = useState(MESSAGES_PER_PAGE);
  const [isLoadingMore, setIsLoadingMore] = useState(false);

  // Scroll & State Persistence
  const conversationStates = useRef<{ [id: string]: { scrollTop: number, visibleCount: number } }>({});
  const prevConversationId = useRef<string | null>(null);

  const scrollY = useRef(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const shouldForceScroll = useRef(false);
  const headerRef = useRef<HTMLDivElement>(null);
  const [headerHeight, setHeaderHeight] = useState(0);

  const attachmentRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const inputContainerRef = useRef<HTMLDivElement>(null);

  // Hidden File Inputs Refs
  const photoInputRef = useRef<HTMLInputElement>(null);
  const documentInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  // Measure Header Height
  useEffect(() => {
    if (headerRef.current) {
      setHeaderHeight(headerRef.current.offsetHeight);
    }
  }, []);

  // Scroll Handler
  const handleScroll = () => {
    if (!scrollRef.current) return;
    const currentScrollY = scrollRef.current.scrollTop;
    const diff = currentScrollY - scrollY.current;

    // Ignore bounce
    if (currentScrollY < 0) return;

    if (diff > 10) {
      // Scrolling Down (towards bottom/newer messages) -> Hide Header
      setIsHeaderVisible(false);
    } else if (diff < -10) {
      // Scrolling Up (towards top/history) -> Show Header
      setIsHeaderVisible(true);
    }

    // Detect if user is near the bottom (within 150px)
    const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
    const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
    setShowScrollToBottom(distanceFromBottom > 150);

    // Clear new message indicator when user scrolls to bottom
    if (distanceFromBottom <= 150) {
      setHasNewMessage(false);
    }

    scrollY.current = currentScrollY;

    // Save scroll state for current conversation
    if (activeConversation && scrollRef.current) {
      conversationStates.current[activeConversation.id] = {
        scrollTop: currentScrollY,
        visibleCount
      };
    }

    // Load more messages when scrolling near the top
    if (currentScrollY < 100 && !isLoadingMore && visibleCount < messages.length) {
      setIsLoadingMore(true);
      const prevScrollHeight = scrollRef.current.scrollHeight;
      setTimeout(() => {
        setVisibleCount(prev => Math.min(prev + MESSAGES_PER_PAGE, messages.length));
        // Preserve scroll position after prepending older messages
        requestAnimationFrame(() => {
          if (scrollRef.current) {
            const newScrollHeight = scrollRef.current.scrollHeight;
            scrollRef.current.scrollTop = newScrollHeight - prevScrollHeight + currentScrollY;
          }
          setIsLoadingMore(false);
        });
      }, 400);
    }
  };

  // Initialize or Update Messages based on Active Conversation
  useEffect(() => {
    if (activeConversation) {
      // Check if we switched conversations
      const isDifferentConversation = activeConversation.id !== prevConversationId.current;

      // Load saved messages
      const hasUserMessages = activeConversation.messages.some(m => m.sender === 'user');
      if (hasUserMessages) {
        setMessages(activeConversation.messages);
      } else {
        setMessages([]);
      }

      if (isDifferentConversation) {
        // Restore state if available
        const savedState = conversationStates.current[activeConversation.id];
        if (savedState) {
          setVisibleCount(savedState.visibleCount);
          // Restore scroll position after render
          requestAnimationFrame(() => {
            if (scrollRef.current) {
              scrollRef.current.scrollTop = savedState.scrollTop;
            }
          });
        } else {
          // Default for new/unvisited conversation
          setVisibleCount(MESSAGES_PER_PAGE);
        }

        // Reset new message indicator on switch
        setHasNewMessage(false);
        prevConversationId.current = activeConversation.id;
      }
    } else {
      // New Chat Default - Start Empty
      setMessages([]);
      setVisibleCount(MESSAGES_PER_PAGE);
      setHasNewMessage(false);
      prevConversationId.current = null;
    }
  }, [activeConversation]);

  // Scroll to bottom logic
  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
      // Sync scroll tracker
      scrollY.current = scrollRef.current.scrollTop;
    }
  };

  // Auto-scroll when messages change or UI expands
  useEffect(() => {
    if (!scrollRef.current) {
      if (shouldForceScroll.current) {
        scrollToBottom();
        shouldForceScroll.current = false;
      }
      return;
    }
    const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
    const distanceFromBottom = scrollHeight - scrollTop - clientHeight;

    if (distanceFromBottom < 150 || shouldForceScroll.current) {
      // User is near the bottom OR forced (user sent message) — auto-scroll
      scrollToBottom();
      shouldForceScroll.current = false;
    } else {
      // User is scrolled up — show new message indicator instead
      setHasNewMessage(true);
    }
  }, [messages, isTyping, activeCommentId]);

  // Auto-scroll on window resize (e.g., keyboard open)
  useEffect(() => {
    const handleResize = () => scrollToBottom();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 100)}px`;
    }
  }, [inputText]);

  // Click outside to close dropdowns
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      // NOTE: We rely on standard Radix UI behavior for closing on outside click for many things,
      // but if we need manual control, we can add it here.
      // For now, ensuring attachment menu closes is fine if we had a ref, but we removed the manual dropdown ref.
      // We can keep attachmentRef logic if we restore the Ref, or just trust the Popover component.
      // The current Popover component from shadcn usually handles outside clicks automatically.
      if (attachmentRef.current && !attachmentRef.current.contains(event.target as Node)) {
        setIsAttachmentMenuOpen(false);
      }
    };

    if (isAttachmentMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isAttachmentMenuOpen]);


  // Wrapper to save chat before navigating
  const handleNavigate = (screen: Screen) => {
    if (messages.length > 1) { // Save if there's more than just the greeting
      onSaveChat(messages);
    }
    navigate(screen);
  };

  const handleSendMessage = async () => {
    if (!inputText.trim()) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      sender: 'user',
      text: inputText,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMsg];
    setMessages(newMessages);
    shouldForceScroll.current = true; // Force scroll to bottom for user messages
    onSaveChat(newMessages);

    setInputText('');
    setIsTyping(true);

    // Pass the selected language context to the AI service
    // Instruction: React naturally in ENGLISH (to be translated). Avoid explanations.
    const contextPrompt = `[Instruction: React naturally to "${userMsg.text}". REPLY IN ENGLISH ONLY. Do NOT define words. Do NOT explain content. Just reply as a friend.]`;

    // Call Convex Action (Llama 3)
    const history = messages.map(m => ({
      role: m.sender === 'user' ? 'user' : 'assistant',
      content: m.text
    }));

    // Add current message properly (User message + Instruction)
    const payload = [...history, { role: 'user', content: contextPrompt }];

    const aiResponseText = await sendMessageAction({ messages: payload });

    // Check if response is an error message
    if (aiResponseText.startsWith && aiResponseText.startsWith("ERROR:")) {
      console.error("Chat error:", aiResponseText);
      // Display error to user but don't crash
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        sender: 'ai',
        text: aiResponseText,
        timestamp: new Date()
      }]);
      return;
    }

    // Call translation if selected language is not English
    let translatedText = undefined;
    if (selectedLanguage.code !== 'en') {
      try {
        const result = await translate({
          text: aiResponseText,
          targetLanguage: selectedLanguage.nllbCode
        });

        // Backend now returns descriptive error messages starting with "ERROR:" on failure.
        // If result is valid (not an error), use it.
        if (result && !result.startsWith("ERROR:")) {
          translatedText = result;
        } else if (result?.startsWith("ERROR:")) {
          // Log the error for debugging
          console.error("Translation error:", result);
          translatedText = "Translation unavailable";
        }
      } catch (error) {
        console.error("Translation failed:", error);
        translatedText = "Translation unavailable";
      }
    }

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      sender: 'ai',
      text: aiResponseText,
      translatedText,
      targetLanguage: selectedLanguage.name,
      timestamp: new Date()
    };

    setIsTyping(false);
    setMessages(prev => {
      const updated = [...prev, aiMsg];
      setTimeout(() => onSaveChat(updated), 0);
      return updated;
    });
  };

  const startRecording = async () => {
    try {
      // Check if the browser supports mediaDevices (requires HTTPS or localhost)
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        alert("Microphone access is not supported. Please ensure you use a secure connection (HTTPS) or localhost.");
        return;
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream, { mimeType: 'audio/webm' });
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        setIsTranscribing(true);
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });

        // Convert Blob to Base64
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64data = reader.result as string;
          const base64String = base64data.split(',')[1];

          try {
            const response = await transcribeAudio({ audioBase64: base64String });
            if (response.text) {
              setInputText(prev => prev ? `${prev} ${response.text}` : response.text);
              // Auto-resize textarea
              setTimeout(() => {
                if (textareaRef.current) {
                  textareaRef.current.style.height = 'auto';
                  textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 100)}px`;
                }
              }, 0);
            }
          } catch (err) {
            console.error("Transcription failed:", err);
          } finally {
            setIsTranscribing(false);
          }
        };

        // Stop all tracks
        stream.getTracks().forEach((track) => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Failed to start recording:", err);
      alert("Could not access microphone.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handlePlayAudio = async (messageId: string, text: string, language: string) => {
    if (playingMessageId === messageId) {
      // Stop current audio
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      }
      setPlayingMessageId(null);
      return;
    }

    setIsSynthesizing(messageId);

    try {
      // Language code for TTS is derived from selectedLanguage name/nllbCode mapping
      const result = await synthesizeSpeech({
        text,
        language: selectedLanguage.code
      });

      if (result.audioBase64) {
        const audioUrl = `data:${result.contentType};base64,${result.audioBase64}`;

        if (audioRef.current) {
          audioRef.current.pause();
        }

        const audio = new Audio(audioUrl);
        audioRef.current = audio;

        audio.onended = () => {
          setPlayingMessageId(null);
        };

        audio.play();
        setPlayingMessageId(messageId);
      }
    } catch (err) {
      console.error("Failed to play audio:", err);
    } finally {
      setIsSynthesizing(null);
    }
  };



  const handleNewChatClick = () => {
    // Save current chat before starting new
    if (messages.length > 1) {
      onSaveChat(messages);
    }

    // Explicitly reset state for new chat to trigger Welcome Mode
    setMessages([]);
    setInputText('');
    setExpandedTranslations({});
    setIsNavOpen(false);
    onNewChat();
  };

  const handleLanguageSelect = (lang: Language) => {
    setSelectedLanguage(lang);
  };

  const handleFeedback = (messageId: string, type: 'up' | 'down') => {
    setMessages(prev => prev.map(m => {
      if (m.id === messageId) {
        // Toggle feedback if already selected
        const newFeedback = m.feedback === type ? undefined : type;
        return { ...m, feedback: newFeedback };
      }
      return m;
    }));
  };

  const toggleCommentBox = (messageId: string) => {
    if (activeCommentId === messageId) {
      setActiveCommentId(null);
      setCommentText('');
    } else {
      setActiveCommentId(messageId);
      setCommentText('');
    }
  };

  const submitComment = (messageId: string) => {
    if (!commentText.trim()) return;

    setMessages(prev => prev.map(m => {
      if (m.id === messageId) {
        // Only allow one comment per message
        if (m.comments && m.comments.length > 0) return m;

        const currentComments = m.comments || [];
        return { ...m, comments: [...currentComments, commentText] };
      }
      return m;
    }));
    // Clear input and close box
    setCommentText('');
    setActiveCommentId(null);
  };

  const toggleTranslation = (messageId: string) => {
    setExpandedTranslations(prev => ({
      ...prev,
      [messageId]: !prev[messageId]
    }));
  };

  // Handle File Selections
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'document') => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      if (type === 'image') {
        const reader = new FileReader();
        reader.onload = (event) => {
          const base64 = event.target?.result as string;
          const userMsg: Message = {
            id: Date.now().toString(),
            sender: 'user',
            text: base64, // Storing data URL in text field for simplicity in this demo
            timestamp: new Date()
          };
          setMessages(prev => [...prev, userMsg]);

          setIsTyping(true);
          // Simulate AI response to image
          setTimeout(() => {
            const aiMsg: Message = {
              id: (Date.now() + 1).toString(),
              sender: 'ai',
              text: "That's a nice image! In Swahili culture, visual storytelling is very important.",
              timestamp: new Date()
            };
            setMessages(prev => [...prev, aiMsg]);
            setIsTyping(false);
          }, 2000);
        };
        reader.readAsDataURL(file);
      } else {
        const userMsg: Message = {
          id: Date.now().toString(),
          sender: 'user',
          text: `ðŸ“„ ${file.name}`,
          timestamp: new Date()
        };
        setMessages(prev => [...prev, userMsg]);

        setIsTyping(true);
        // Simulate AI response to document
        setTimeout(() => {
          const aiMsg: Message = {
            id: (Date.now() + 1).toString(),
            sender: 'ai',
            text: `I've received "${file.name}". Would you like me to summarize it or translate it?`,
            timestamp: new Date()
          };
          setMessages(prev => [...prev, aiMsg]);
          setIsTyping(false);
        }, 1500);
      }
    }
    // Reset file input so same file can be selected again if needed
    e.target.value = '';
    setIsAttachmentMenuOpen(false);
  };

  // Removed local filtering/helper functions in favor of LanguageSelector component logic

  return (
    <div className="flex h-[100dvh] bg-background-light dark:bg-background-dark relative overflow-hidden transition-colors duration-300">
      {/* Hidden File Inputs */}
      <input type="file" ref={photoInputRef} className="hidden" accept="image/*,video/*" onChange={(e) => handleFileSelect(e, 'image')} />
      <input type="file" ref={documentInputRef} className="hidden" accept=".pdf,.doc,.docx,.txt" onChange={(e) => handleFileSelect(e, 'document')} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="environment" onChange={(e) => handleFileSelect(e, 'image')} />

      {/* Navigation Drawer using Sheet */}
      <Sheet open={isNavOpen} onOpenChange={setIsNavOpen}>
        <SheetContent side="left" className="w-[300px] sm:w-[350px] p-0 border-r border-border bg-background">
          <div className="flex flex-col h-full bg-muted/30">
            <div className="p-6">
              <SheetHeader className="text-left mb-8">
                <div className="flex items-center gap-4">
                  <Avatar className="w-12 h-12 border-2 border-primary/20">
                    <AvatarImage src={user.avatar} />
                    <AvatarFallback>{user.name[0]}</AvatarFallback>
                  </Avatar>
                  <div className="space-y-0.5">
                    <SheetTitle className="text-lg font-bold tracking-tight">{user.name}</SheetTitle>
                    <p className="text-xs text-muted-foreground font-medium uppercase tracking-wider">{user.handle}</p>
                  </div>
                </div>
              </SheetHeader>

              <Button
                onClick={handleNewChatClick}
                className="w-full h-12 rounded-xl gap-2 font-bold shadow-lg shadow-primary/20 transition-all hover:scale-[1.02] active:scale-95"
              >
                <Plus className="w-5 h-5" />
                Kaanze
              </Button>
            </div>

            <nav className="flex-1 px-3 space-y-1 overflow-y-auto">


              <DrawerItem
                icon={<History className="w-5 h-5" />}
                label="Kaendelee"
                onClick={() => handleNavigate(Screen.SAVED_CONVERSATIONS)}
              />

              <DrawerItem
                icon={<Flame className="w-5 h-5" />}
                label="Changa"
                count={notificationCounts?.contributions}
                onClick={() => handleNavigate(Screen.CONTRIBUTIONS)}
              />
              <DrawerItem
                icon={<MessagesSquare className="w-5 h-5" />}
                label="Mushenee"
                onClick={() => handleNavigate(Screen.MESSAGES)}
              />

              {user.role === 'moderator' || user.role === 'admin' && (
                <DrawerItem
                  icon={<ShieldCheck className="w-5 h-5" />}
                  label="Moderation"
                  count={notificationCounts?.moderation}
                  onClick={() => handleNavigate(Screen.MODERATION_DASHBOARD)}
                />
              )}

            </nav>

            <div className="p-4 mt-auto">
              <DrawerItem
                icon={<Activity className="w-5 h-5" />}
                label="Diagnostics"
                onClick={runDiagnostics}
              />
              <DrawerItem
                icon={<Settings className="w-5 h-5" />}
                label="Settings"
                onClick={() => handleNavigate(Screen.SETTINGS)}
              />
            </div>
          </div>
        </SheetContent>
      </Sheet>

      {/* Main Content */}
      <div className="flex-1 flex flex-col w-full h-full relative">
        {/* Header - Hidden in welcome mode, visible when chatting */}
        {!isWelcomeMode && (
          <div
            ref={headerRef}
            className="absolute top-0 left-0 right-0 z-20 transition-all duration-300 ease-in-out bg-background/95 backdrop-blur-md shadow-sm"
            style={{ marginTop: isHeaderVisible ? 0 : -headerHeight }}
          >
            <header className="h-16 flex items-center justify-between px-4 shrink-0 transition-colors duration-300">
              <div className="flex items-center gap-3">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setIsNavOpen(true)}
                  className="rounded-full transition-colors"
                  aria-label="Toggle navigation"
                >
                  <Menu className="w-6 h-6" />
                </Button>
                <div className="flex flex-col cursor-pointer" onClick={handleNewChatClick}>
                  <h1 className="text-lg font-bold text-foreground truncate max-w-[200px] leading-tight tracking-tight hover:text-primary transition-colors">
                    {activeConversation ? activeConversation.title : 'Samiati'}
                  </h1>
                </div>
              </div>
            </header>
          </div>
        )}

        {/* Welcome Mode - Google-style centered layout */}
        {isWelcomeMode ? (
          <div className="flex-1 relative flex flex-col overflow-y-auto w-full">
            {/* Menu button in corner for welcome mode */}
            <div className="sticky top-0 left-0 w-full z-10 pointer-events-none p-4 flex justify-between items-start">
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setIsNavOpen(true)}
                className="rounded-full transition-colors pointer-events-auto bg-background/50 backdrop-blur-sm"
                aria-label="Toggle navigation"
              >
                <Menu className="w-6 h-6" />
              </Button>
              <div className="w-10" />
            </div>

            <div className="flex-1 flex flex-col items-center justify-center min-h-full w-full px-4 -mt-20 pb-8 animate-in fade-in duration-500">

              {/* Logo and Branding */}
              <div className="flex flex-col items-center mb-8 shrink-0">
                <div className="hover:scale-105 transition-transform duration-300 mb-2">
                  <SamiatiLogo size={80} className="scale-110" />
                </div>
                <p className="text-muted-foreground text-sm md:text-base font-medium text-center">
                  Experience your Culture
                </p>
              </div>

              {/* Centered Input Bar */}
              <div className="w-full max-w-2xl shrink-0 px-2 sm:px-0">
                <div ref={inputContainerRef} className="bg-background border border-border/40 rounded-[24px] px-3 sm:px-4 py-3 flex flex-col gap-2 sm:gap-3 transition-all shadow-xl shadow-primary/5 focus-within:shadow-2xl focus-within:ring-1 focus-within:ring-primary/20">

                  {/* Top Layer: Text Input */}
                  <div className="w-full">
                    <textarea
                      ref={textareaRef}
                      value={inputText}
                      onChange={(e) => setInputText(e.target.value)}
                      onFocus={() => {
                        // Scroll to end (bottom) to maximize space above for the logo
                        setTimeout(() => {
                          inputContainerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
                        }, 300);
                      }}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                          e.preventDefault();
                          handleSendMessage();
                        }
                      }}
                      placeholder="Type or Speak..."
                      className="w-full bg-transparent border-none text-foreground placeholder-muted-foreground/70 focus:ring-0 outline-none text-base md:text-lg resize-none min-h-[40px] max-h-[160px] p-0 font-medium leading-relaxed"
                      rows={1}
                    />
                  </div>

                  {/* Bottom Layer: Actions */}
                  <div className="flex items-center justify-between w-full">
                    {/* Left: Language Selector */}
                    <LanguageSelector
                      selectedLanguage={selectedLanguage}
                      onSelect={handleLanguageSelect}
                    />

                    {/* Right: Actions */}
                    <div className="flex items-center gap-1 sm:gap-2 shrink-0">
                      {/* Attachments Menu Popover */}
                      <Popover open={isAttachmentMenuOpen} onOpenChange={setIsAttachmentMenuOpen}>
                        <PopoverTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="rounded-full text-muted-foreground hover:text-primary transition-colors h-9 w-9 hover:bg-muted/50"
                            aria-label="Add attachments"
                          >
                            <PlusCircle className="w-5 h-5" />
                          </Button>
                        </PopoverTrigger>
                        <PopoverContent side="top" align="end" className="w-[180px] p-1.5 mb-3 rounded-2xl shadow-xl border-border bg-background">
                          <AttachmentItem
                            icon={<ImageIcon className="w-4 h-4 text-blue-500" />}
                            label="Photo / Video"
                            onClick={() => photoInputRef.current?.click()}
                          />
                          <AttachmentItem
                            icon={<FileText className="w-4 h-4 text-orange-500" />}
                            label="Document"
                            onClick={() => documentInputRef.current?.click()}
                          />
                          <AttachmentItem
                            icon={<Camera className="w-4 h-4 text-green-500" />}
                            label="Live Camera"
                            onClick={() => cameraInputRef.current?.click()}
                          />
                        </PopoverContent>
                      </Popover>

                      {/* Microphone Button */}
                      <Button
                        size="icon"
                        onClick={isRecording ? stopRecording : startRecording}
                        disabled={isTranscribing}
                        className={cn(
                          "w-9 h-9 rounded-full transition-all duration-300 shadow-sm transition-transform active:scale-95",
                          isTranscribing
                            ? "bg-muted text-muted-foreground opacity-50 cursor-not-allowed"
                            : isRecording
                              ? "bg-red-500 text-white animate-pulse"
                              : "bg-muted/50 text-muted-foreground hover:text-foreground hover:bg-muted"
                        )}
                        aria-label="Toggle voice recording"
                      >
                        {isTranscribing ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : isRecording ? (
                          <Square className="w-4 h-4 fill-current" />
                        ) : (
                          <Mic className="w-4 h-4" />
                        )}
                      </Button>

                      <Button
                        size="icon"
                        onClick={handleSendMessage}
                        disabled={!inputText.trim() || isTranscribing}
                        className={cn(
                          "w-9 h-9 rounded-full transition-all duration-300 shadow-sm transition-transform active:scale-95",
                          inputText.trim() && !isTranscribing
                            ? "bg-primary text-primary-foreground opacity-100 hover:scale-105"
                            : "bg-muted text-muted-foreground opacity-50 cursor-not-allowed"
                        )}
                      >
                        <ArrowUp className="w-5 h-5 stroke-[2.5]" />
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <>
            {/* Chat Area */}
            <main
              className="flex-1 overflow-y-auto overflow-x-hidden pt-20 px-4 pb-4 space-y-6 scroll-smooth overscroll-contain"
              ref={scrollRef}
              onScroll={handleScroll}
              style={{ WebkitOverflowScrolling: 'touch' }}
            >
              {/* Loading older messages indicator */}
              {isLoadingMore && (
                <div className="flex items-center justify-center py-3">
                  <Loader2 className="w-5 h-5 animate-spin text-primary" />
                  <span className="ml-2 text-xs font-medium text-muted-foreground">Loading older messages...</span>
                </div>
              )}
              {/* Show indicator for hidden history */}
              {!isLoadingMore && visibleCount < messages.length && (
                <div className="flex items-center justify-center py-2">
                  <span className="text-[10px] font-bold text-muted-foreground/50 uppercase tracking-wider">↑ Scroll up for older messages</span>
                </div>
              )}
              {/* Messages */}
              {messages.slice(-visibleCount).map((msg, index) => (
                <div key={msg.id} className={cn(
                  "flex flex-col gap-1 group/msg", // Reduced gap
                  msg.sender === 'user' ? 'items-end' : 'items-start'
                )}>
                  <div className={cn(
                    "flex items-start gap-3 w-full max-w-[90%] md:max-w-[80%]",
                    msg.sender === 'user' && 'flex-row-reverse self-end'
                  )}>
                    {msg.sender === 'ai' ? (
                      <Avatar className="w-8 h-8 shrink-0 shadow-sm mt-1 bg-transparent p-0">
                        <AvatarImage src="/samiati-logo.svg" className="object-cover rounded-md" />
                        <AvatarFallback>AI</AvatarFallback>
                      </Avatar>
                    ) : (
                      <Avatar className="w-8 h-8 shrink-0 border border-border shadow-sm mt-1">
                        <AvatarImage src={user.avatar} />
                        <AvatarFallback>{user.name[0]}</AvatarFallback>
                      </Avatar>
                    )}

                    <div className={cn(
                      "relative transition-all",
                      msg.sender === 'user'
                        ? 'p-4 rounded-2xl shadow-sm bg-[#EDE4D9] dark:bg-[#4A4035] text-[#4A4035] dark:text-[#EDE4D9]'
                        : 'p-0 text-foreground bg-transparent'
                    )}>
                      {msg.text.startsWith('data:image') ? (
                        <img src={msg.text} alt="User upload" className="rounded-2xl max-h-72 w-full object-cover shadow-inner" />
                      ) : (
                        <p className="text-sm md:text-base leading-relaxed tracking-tight font-medium whitespace-pre-wrap">
                          {/* Show translated text for AI messages if available AND language is not English, otherwise show original text */}
                          {msg.sender === 'ai' && selectedLanguage.code !== 'en' && msg.translatedText ? msg.translatedText : msg.text}
                        </p>
                      )}

                      {/* Collapsible English Original - Only for AI messages with translations AND when not in English mode */}
                      {msg.sender === 'ai' && selectedLanguage.code !== 'en' && (
                        <div className="mt-3 pt-3 border-t border-border/50">
                          {/* Toggle Button for English Original */}
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => toggleTranslation(msg.id)}
                            className="h-7 px-2.5 rounded-full gap-1.5 text-[10px] font-bold uppercase tracking-wider text-muted-foreground hover:text-foreground transition-all"
                          >
                            {expandedTranslations[msg.id] ? (
                              <>
                                <ChevronUp className="w-3 h-3" />
                                Hide English
                              </>
                            ) : (
                              <>
                                <ChevronDown className="w-3 h-3" />
                                View English
                              </>
                            )}
                          </Button>

                          {/* English Original (Collapsible) */}
                          {expandedTranslations[msg.id] && (
                            <div className="mt-2 pt-2 border-t border-border/30 animate-in fade-in slide-in-from-top-2 duration-300">
                              <div className="flex items-center gap-1.5 text-[10px] font-black text-muted-foreground uppercase tracking-widest mb-1.5 opacity-60">
                                <Globe className="w-3 h-3" />
                                English Original
                              </div>
                              <p className="text-sm md:text-base leading-relaxed tracking-tight font-medium whitespace-pre-wrap border-l-2 border-muted-foreground/20 pl-3 py-0.5 text-muted-foreground">
                                {msg.text}
                              </p>
                            </div>
                          )}
                        </div>
                      )}

                      {/* User Message Timestamp (Absolute) */}
                      {msg.sender === 'user' && (
                        <span className="absolute -bottom-5 right-0 text-[10px] font-bold text-muted-foreground/0 group-hover/msg:text-muted-foreground/60 transition-all">
                          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      )}
                    </div>
                  </div>

                  {/* AI Actions Row: Thumbs | Copy | Feedback | Audio */}
                  {msg.sender === 'ai' && (
                    <div className="flex flex-wrap items-center gap-x-2 gap-y-2 ml-10 mt-2 mb-2 transition-opacity duration-200">

                      {/* TTS / Speaker Button */}
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handlePlayAudio(msg.id, msg.translatedText || msg.text, msg.targetLanguage || 'sw')}
                        className={cn(
                          "h-6 w-6 rounded-full transition-all",
                          playingMessageId === msg.id
                            ? "text-primary bg-primary/10 animate-pulse"
                            : isSynthesizing === msg.id
                              ? "text-muted-foreground opacity-50 cursor-not-allowed"
                              : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
                        )}
                        disabled={isSynthesizing === msg.id}
                        title={playingMessageId === msg.id ? "Stop audio" : "Listen"}
                      >
                        {isSynthesizing === msg.id ? (
                          <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : playingMessageId === msg.id ? (
                          <Square className="w-3.5 h-3.5 fill-current" />
                        ) : (
                          <Volume2 className="w-3.5 h-3.5" />
                        )}
                      </Button>

                      {/* Divider */}
                      <div className="h-3 w-[1px] bg-border" />

                      {/* Thumbs Up/Down */}
                      <div className="flex items-center gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleFeedback(msg.id, 'up')}
                          className={cn(
                            "h-6 w-6 rounded-full hover:bg-muted/50 transition-colors",
                            msg.feedback === 'up' ? "text-primary" : "text-muted-foreground"
                          )}
                        >
                          <ThumbsUp className={cn("w-3.5 h-3.5", msg.feedback === 'up' && "fill-current")} />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleFeedback(msg.id, 'down')}
                          className={cn(
                            "h-6 w-6 rounded-full hover:bg-muted/50 transition-colors",
                            msg.feedback === 'down' ? "text-red-500" : "text-muted-foreground"
                          )}
                        >
                          <ThumbsDown className={cn("w-3.5 h-3.5", msg.feedback === 'down' && "fill-current")} />
                        </Button>
                      </div>

                      {/* Divider */}
                      <div className="h-3 w-[1px] bg-border" />

                      {/* Copy Button */}
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleCopy(msg.text, msg.id)}
                        className="h-6 w-6 rounded-full hover:bg-muted/50 text-muted-foreground hover:text-foreground transition-all"
                        title="Copy text"
                      >
                        {copiedMessageId === msg.id ? (
                          <Check className="w-3.5 h-3.5 text-green-500" />
                        ) : (
                          <Copy className="w-3.5 h-3.5" />
                        )}
                      </Button>

                      {/* Feedback Button (Icon Only) */}
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => toggleCommentBox(msg.id)}
                        className="h-6 w-6 rounded-full hover:bg-muted/50 text-muted-foreground hover:text-foreground transition-all"
                        title="Feedback"
                      >
                        <MessageCircle className="w-3.5 h-3.5" />
                      </Button>

                    </div>
                  )}



                  {/* Feedback Expansion */}
                  {(activeCommentId === msg.id) && (
                    <div className="bg-muted/50 rounded-2xl p-3 border border-border/50 space-y-3 animate-in fade-in slide-in-from-top-1">
                      {msg.comments && msg.comments.length > 0 && (
                        <div className="space-y-2">
                          {msg.comments.map((comment, i) => (
                            <div key={i} className="flex gap-2 items-start">
                              <div className="mt-1 w-1 h-1 bg-primary rounded-full shrink-0" />
                              <p className="text-xs font-medium text-foreground/70 leading-relaxed italic">{comment}</p>
                            </div>
                          ))}
                        </div>
                      )}

                      {(!msg.comments || msg.comments.length === 0) ? (
                        <div className="flex gap-2">
                          <Input
                            value={commentText}
                            onChange={(e) => setCommentText(e.target.value)}
                            placeholder="Improve this..."
                            className="h-9 text-xs rounded-xl bg-background border-none focus-visible:ring-1 focus-visible:ring-primary/50 font-medium"
                            onKeyDown={(e) => e.key === 'Enter' && submitComment(msg.id)}
                          />
                          <Button
                            size="icon"
                            variant="default"
                            className="h-9 w-9 rounded-xl shrink-0 shadow-lg shadow-primary/20"
                            onClick={() => submitComment(msg.id)}
                            disabled={!commentText.trim()}
                          >
                            <ArrowUp className="w-4 h-4" />
                          </Button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2 text-[10px] font-black text-primary uppercase tracking-[0.1em] py-1 border-t border-primary/10">
                          <ShieldCheck className="w-3 h-3" />
                          Knowledge Contribution Received
                        </div>
                      )}
                    </div>
                  )}
                </div>

              ))}

              {isTyping && (
                <div className="flex items-start gap-3 w-full self-start">
                  <Avatar className="w-8 h-8 shrink-0 border border-primary/20 shadow-sm animate-pulse">
                    <AvatarFallback>...</AvatarFallback>
                  </Avatar>
                  <div className="bg-muted/30 border border-border p-4 rounded-3xl rounded-tl-none flex gap-1.5 items-center shadow-sm">
                    <span className="w-2 h-2 bg-primary/40 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                    <span className="w-2 h-2 bg-primary/40 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                    <span className="w-2 h-2 bg-primary/40 rounded-full animate-bounce"></span>
                  </div>
                </div>
              )}
            </main>

            {/* Scroll to Bottom FAB */}
            {showScrollToBottom && (
              <div className="absolute bottom-24 right-4 z-30 flex flex-col items-end gap-2">
                {/* New message indicator */}
                {hasNewMessage && (
                  <button
                    onClick={() => {
                      scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
                      setHasNewMessage(false);
                    }}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-primary text-primary-foreground text-xs font-bold shadow-lg hover:shadow-xl hover:scale-105 active:scale-95 transition-all duration-200 animate-in fade-in slide-in-from-bottom-2"
                  >
                    <ArrowDown className="w-3.5 h-3.5" />
                    New message
                  </button>
                )}
                {/* Scroll to bottom button */}
                <button
                  onClick={() => {
                    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
                    setHasNewMessage(false);
                  }}
                  className="w-10 h-10 rounded-full bg-background border border-border shadow-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:shadow-xl hover:scale-110 active:scale-95 transition-all duration-200 animate-in fade-in zoom-in-75"
                  aria-label="Scroll to bottom"
                >
                  <ArrowDown className="w-5 h-5" />
                </button>
              </div>
            )}

            {/* Standardized Input Area */}
            <div className="bg-background p-2 shrink-0 transition-colors duration-300 relative z-20 pb-4">
              <div ref={inputContainerRef} className="max-w-4xl mx-auto bg-background/50 border border-border/40 rounded-[24px] px-4 py-3 flex flex-col gap-2 transition-all shadow-sm focus-within:shadow-md focus-within:ring-1 focus-within:ring-primary/10 group backdrop-blur-sm">

                {/* Top Layer: Text Input */}
                <div className="w-full">
                  <textarea
                    ref={textareaRef}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    onFocus={() => {
                      // Double scroll attempt to catch immediate focus and post-keyboard animation
                      setTimeout(() => {
                        inputContainerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
                      }, 100);
                      setTimeout(() => {
                        inputContainerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
                      }, 500);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        handleSendMessage();
                      }
                    }}
                    placeholder="Type or Speak..."
                    className="w-full bg-transparent border-none text-foreground placeholder-muted-foreground/70 focus:ring-0 outline-none text-base md:text-lg resize-none min-h-[40px] max-h-[160px] p-0 font-medium leading-relaxed"
                    rows={1}
                  />
                </div>

                {/* Bottom Layer: Actions */}
                <div className="flex items-center justify-between w-full">
                  {/* Left: Language Selector */}
                  <LanguageSelector
                    selectedLanguage={selectedLanguage}
                    onSelect={handleLanguageSelect}
                  />

                  {/* Right: Actions */}
                  <div className="flex items-center gap-2">
                    {/* Attachments Menu Popover */}
                    <Popover open={isAttachmentMenuOpen} onOpenChange={setIsAttachmentMenuOpen}>
                      <PopoverTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="rounded-full text-muted-foreground hover:text-primary transition-colors h-9 w-9 hover:bg-muted/50"
                          aria-label="Add attachments"
                        >
                          <PlusCircle className="w-5 h-5" />
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent side="top" align="end" className="w-[180px] p-1.5 mb-3 rounded-2xl shadow-xl border-border bg-background">
                        <AttachmentItem
                          icon={<ImageIcon className="w-4 h-4 text-blue-500" />}
                          label="Photo / Video"
                          onClick={() => photoInputRef.current?.click()}
                        />
                        <AttachmentItem
                          icon={<FileText className="w-4 h-4 text-orange-500" />}
                          label="Document"
                          onClick={() => documentInputRef.current?.click()}
                        />
                        <AttachmentItem
                          icon={<Camera className="w-4 h-4 text-green-500" />}
                          label="Live Camera"
                          onClick={() => cameraInputRef.current?.click()}
                        />
                      </PopoverContent>
                    </Popover>

                    {/* Microphone Button */}
                    <Button
                      size="icon"
                      onClick={isRecording ? stopRecording : startRecording}
                      disabled={isTranscribing}
                      className={cn(
                        "w-9 h-9 rounded-full transition-all duration-300 shadow-sm transition-transform active:scale-95",
                        isTranscribing
                          ? "bg-muted text-muted-foreground opacity-50 cursor-not-allowed"
                          : isRecording
                            ? "bg-red-500 text-white animate-pulse"
                            : "bg-muted/50 text-muted-foreground hover:text-foreground hover:bg-muted"
                      )}
                      aria-label="Toggle voice recording"
                    >
                      {isTranscribing ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : isRecording ? (
                        <Square className="w-4 h-4 fill-current" />
                      ) : (
                        <Mic className="w-4 h-4" />
                      )}
                    </Button>

                    <Button
                      size="icon"
                      onClick={handleSendMessage}
                      disabled={!inputText.trim() || isTranscribing}
                      className={cn(
                        "w-9 h-9 rounded-full transition-all duration-300 shadow-sm transition-transform active:scale-95",
                        inputText.trim() && !isTranscribing
                          ? "bg-primary text-primary-foreground opacity-100 hover:scale-105"
                          : "bg-muted text-muted-foreground opacity-50 cursor-not-allowed"
                      )}
                    >
                      <ArrowUp className="w-5 h-5 stroke-[2.5]" />
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          </>
        )
        }
      </div >

      {/* Diagnostics Dialog */}
      <Dialog open={showDiagnostics} onOpenChange={setShowDiagnostics}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>AI Services Diagnostics</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 max-h-96 overflow-y-auto">
            {isRunningDiagnostics ? (
              <div className="flex items-center gap-2 text-muted-foreground">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>Running diagnostics...</span>
              </div>
            ) : (
              diagnosticResults.map((result, index) => (
                <div 
                  key={index} 
                  className={`p-3 rounded-lg border ${
                    result.status === 'ok' ? 'border-green-500 bg-green-500/10' :
                    result.status === 'warning' ? 'border-yellow-500 bg-yellow-500/10' :
                    'border-red-500 bg-red-500/10'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <span className={`font-semibold ${
                      result.status === 'ok' ? 'text-green-500' :
                      result.status === 'warning' ? 'text-yellow-500' :
                      'text-red-500'
                    }`}>
                      {result.status === 'ok' ? '✓' : result.status === 'warning' ? '⚠' : '✗'}
                    </span>
                    <span className="font-medium">{result.service}</span>
                  </div>
                  <p className="text-sm mt-1">{result.message}</p>
                  {result.details && (
                    <p className="text-xs mt-1 text-muted-foreground">{result.details}</p>
                  )}
                </div>
              ))
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div >
  );
};

export default ChatScreen;

"use client";

import React, { useState } from 'react';
import { Screen, Community } from '@/types';
import { useFuzzySearch } from '@/hooks/useFuzzySearch';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ArrowLeft, Search, Plus } from "lucide-react";

import { CommunityCard } from '@/components/social/CommunityCard';

import { INITIAL_COMMUNITIES } from '@/data/mock';

interface Props {
    navigate: (screen: Screen, params?: any) => void;
    goBack: () => void;
    communities?: Community[]; // New prop
}

const CommunitiesScreen: React.FC<Props> = ({ navigate, goBack, communities: initialCommunities }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [communities, setCommunities] = useState<Community[]>(initialCommunities || INITIAL_COMMUNITIES);

    // Update local state if prop changes
    React.useEffect(() => {
        if (initialCommunities) {
            setCommunities(initialCommunities);
        }
    }, [initialCommunities]);

    const searchKeys = React.useMemo(() => ['name', 'description'], []);
    const filtered = useFuzzySearch(communities, searchQuery, searchKeys);

    const handleJoin = (id: string) => {
        setCommunities(prev => prev.map(c => {
            if (c.id === id) {
                const isJoined = c.role !== 'none';
                return {
                    ...c,
                    role: isJoined ? 'none' : 'member',
                    memberCount: isJoined ? c.memberCount - 1 : c.memberCount + 1
                };
            }
            return c;
        }));
    };

    const handleCommunityClick = (id: string) => {
        const community = communities.find(c => c.id === id);
        if (community) {
            navigate(Screen.GROUP_VIEW, { community });
        }
    };

    return (
        <div className="flex flex-col min-h-screen bg-background">
            <header className="flex items-center p-4 bg-background/95 backdrop-blur sticky top-0 z-10 border-b border-border">
                <Button variant="ghost" size="icon" onClick={goBack} className="-ml-2 rounded-full">
                    <ArrowLeft className="w-6 h-6" />
                </Button>
                <h1 className="flex-1 text-xl font-bold ml-2">Communities</h1>
                <Button size="icon" variant="ghost" className="rounded-full">
                    <Plus className="w-6 h-6" />
                </Button>
            </header>

            <div className="p-4 bg-muted/30 border-b border-border">
                <div className="relative">
                    <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Discover communities..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-9 bg-background rounded-full border-border/60"
                    />
                </div>
            </div>

            <main className="flex-1 p-4 grid gap-4 sm:grid-cols-2">
                {filtered.map(community => (
                    <CommunityCard
                        key={community.id}
                        community={community}
                        onJoin={handleJoin}
                        onClick={handleCommunityClick}
                    />
                ))}
            </main>
        </div>
    );
};

export default CommunitiesScreen;

﻿"use client";
import React, { useState, useRef, useEffect } from 'react';
import { Screen, User } from '@/types';
import {
  X,
  Send,
  Globe,
  Lock,
  LockKeyholeOpen,
  AtSign,
  Image as ImageIcon,
  BarChart2,
  AlertCircle,
  Plus,
  Trash2,
  ChevronDown,
  Smile,
  FileVideo
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import {
  Popover,
  PopoverTrigger,
  PopoverContent,
} from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

interface Props {
  navigate: (screen: Screen) => void;
  goBack: () => void;
  onPost: (content: string, image?: string, postData?: any) => void;
  user: User;
}

const ComposePostScreen: React.FC<Props> = ({ navigate, goBack, onPost, user }) => {
  const [text, setText] = useState('');
  const [image, setImage] = useState<string | null>(null);
  const [cw, setCw] = useState<string>('');
  const [showCw, setShowCw] = useState(false);
  const [visibility, setVisibility] = useState<'Public' | 'Unlisted' | 'Followers' | 'Direct'>('Public');
  const [showVisibilityMenu, setShowVisibilityMenu] = useState(false);

  // Poll State
  const [showPoll, setShowPoll] = useState(false);
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);
  const [pollDuration, setPollDuration] = useState('1 day');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const firstPollInputRef = useRef<HTMLInputElement>(null);

  // Focus first poll input when opened
  useEffect(() => {
    if (showPoll && firstPollInputRef.current) {
      firstPollInputRef.current.focus();
    }
  }, [showPoll]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event) => {
        setImage(event.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePublish = () => {
    if (!text.trim() && !image && !showPoll) return;

    // Structure post data
    const postData: any = {
      visibility,
      cw: showCw && cw.trim() ? cw : undefined,
    };

    if (showPoll) {
      const validOptions = pollOptions.filter(o => o.trim().length > 0);
      if (validOptions.length >= 2) {
        postData.poll = {
          options: validOptions.map((label, idx) => ({
            id: `opt-${idx}`,
            label,
            votes: 0
          })),
          totalVotes: 0,
          endsAt: pollDuration,
          userVotedOptionId: null
        };
      }
    }

    // Pass structured data. Content is just text, CW is separate.
    onPost(text, image || undefined, postData);
    goBack();
  };

  const handlePollOptionChange = (index: number, value: string) => {
    if (value.length > 25) return; // Character limit for UI cleanliness
    const newOptions = [...pollOptions];
    newOptions[index] = value;
    setPollOptions(newOptions);
  };

  const addPollOption = () => {
    if (pollOptions.length < 4) {
      setPollOptions([...pollOptions, '']);
    }
  };

  const removePollOption = (index: number) => {
    if (pollOptions.length > 2) {
      setPollOptions(pollOptions.filter((_, i) => i !== index));
    }
  };

  const getVisibilityIcon = () => {
    switch (visibility) {
      case 'Public': return <Globe className="w-4 h-4" />;
      case 'Unlisted': return <LockKeyholeOpen className="w-4 h-4" />;
      case 'Followers': return <Lock className="w-4 h-4" />;
      case 'Direct': return <AtSign className="w-4 h-4" />;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-background transition-colors duration-300">
      {/* Header */}
      <header className="flex items-center justify-between px-4 py-2 border-b border-border bg-background/95 backdrop-blur-md sticky top-0 z-30">
        <Button
          variant="ghost"
          size="sm"
          onClick={goBack}
          className="text-muted-foreground hover:text-foreground font-bold"
        >
          Cancel
        </Button>
        <Button
          onClick={handlePublish}
          disabled={(!text.trim() && !image && !showPoll) || (showPoll && pollOptions.filter(o => o.trim()).length < 2)}
          className="rounded-full gap-2 font-black text-xs uppercase tracking-widest px-6 h-9"
        >
          <Send className="w-3.5 h-3.5" />
          Publish
        </Button>
      </header>

      <main className="flex-1 p-4 overflow-y-auto">
        <div className="flex gap-4">
          <Avatar className="w-12 h-12 rounded-xl object-cover shrink-0 border border-border">
            <AvatarImage src={user.avatar} className="object-cover" />
            <AvatarFallback>{user.name[0]}</AvatarFallback>
          </Avatar>
          <div className="flex-1 flex flex-col gap-4">
            {showCw && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="flex items-center gap-2 mb-1.5 ml-1">
                  <AlertCircle className="w-3 h-3 text-primary" />
                  <span className="text-[10px] font-black uppercase tracking-widest text-primary">Content Warning</span>
                </div>
                <Input
                  type="text"
                  value={cw}
                  onChange={(e) => setCw(e.target.value)}
                  placeholder="What's this about? (e.g. Spoilers, Politics)"
                  className="w-full bg-muted/30 border-primary/20 rounded-xl h-10 text-sm focus-visible:ring-primary/20"
                  autoFocus
                />
              </div>
            )}

            <Textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Habari gani? What's the news?"
              className="w-full bg-transparent text-xl border-none p-0 focus-visible:ring-0 placeholder:text-muted-foreground/50 resize-none min-h-[160px] leading-relaxed font-medium"
              autoFocus={!showCw}
            />

            {image && (
              <div className="relative mt-2 rounded-2xl overflow-hidden group w-fit border border-border shadow-xl">
                <img src={image} alt="Preview" className="max-w-full h-auto max-h-80 object-cover rounded-2xl group-hover:scale-105 transition-transform duration-500" />
                <Button
                  size="icon"
                  variant="destructive"
                  onClick={() => setImage(null)}
                  className="absolute top-3 right-3 h-8 w-8 rounded-full opacity-90 backdrop-blur-md shadow-lg"
                >
                  <X className="w-4 h-4" />
                </Button>
              </div>
            )}

            {showPoll && (
              <Card className="bg-muted/30 p-4 rounded-2xl border-primary/10 animate-in fade-in slide-in-from-top-2 duration-300 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-2">
                    <BarChart2 className="w-4 h-4 text-primary" />
                    <h4 className="text-xs font-black uppercase tracking-[0.15em] text-foreground/80">Active Poll</h4>
                  </div>
                  <Button variant="ghost" size="icon" onClick={() => setShowPoll(false)} className="h-8 w-8 rounded-full text-muted-foreground">
                    <X className="w-4 h-4" />
                  </Button>
                </div>
                <div className="space-y-3">
                  {pollOptions.map((opt, idx) => (
                    <div key={idx} className="flex gap-3 items-center">
                      <div className="flex-1 relative">
                        <Input
                          ref={idx === 0 ? firstPollInputRef : null}
                          value={opt}
                          onChange={(e) => handlePollOptionChange(idx, e.target.value)}
                          placeholder={`Choice ${idx + 1}...`}
                          className="h-10 bg-background border-border/50 rounded-xl pr-10 text-sm focus-visible:ring-primary/20"
                        />
                        {opt.length > 20 && (
                          <span className="absolute right-3 top-3 text-[10px] text-muted-foreground font-mono font-bold">{25 - opt.length}</span>
                        )}
                      </div>
                      {pollOptions.length > 2 && (
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => removePollOption(idx)}
                          className="text-muted-foreground hover:text-destructive h-10 w-10 shrink-0"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  ))}
                  {pollOptions.length < 4 && (
                    <Button
                      variant="outline"
                      onClick={addPollOption}
                      className="w-full h-10 rounded-xl gap-2 font-bold text-xs border-dashed border-2 hover:border-primary/50 hover:bg-primary/5 transition-all"
                    >
                      <Plus className="w-3.5 h-3.5" /> Add another choice
                    </Button>
                  )}
                </div>
                <div className="mt-4 pt-4 border-t border-border flex items-center justify-between">
                  <span className="text-[10px] text-muted-foreground font-black uppercase tracking-[0.1em]">Expiration</span>
                  <select
                    value={pollDuration}
                    onChange={(e) => setPollDuration(e.target.value)}
                    className="bg-muted/50 text-[11px] font-bold text-foreground px-3 py-1.5 rounded-lg outline-none cursor-pointer border border-border/50 hover:border-primary/30 transition-all uppercase tracking-wider"
                  >
                    <option value="5 minutes">5 minutes</option>
                    <option value="1 hour">1 hour</option>
                    <option value="1 day">1 day (Default)</option>
                    <option value="3 days">3 days</option>
                    <option value="7 days">7 days</option>
                  </select>
                </div>
              </Card>
            )}
          </div>
        </div>
      </main>

      {/* Toolbar */}
      <div className="px-4 py-3 border-t border-border bg-background pb-safe sticky bottom-0 z-30 shadow-[0_-4px_20px_rgba(0,0,0,0.03)] dark:shadow-none">
        <div className="flex items-center justify-between max-w-2xl mx-auto">
          <div className="flex items-center gap-1">
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              accept="image/*"
              onChange={handleImageSelect}
            />
            <Button
              variant="ghost"
              size="icon"
              onClick={() => fileInputRef.current?.click()}
              className="rounded-full text-muted-foreground hover:text-primary h-10 w-10"
              title="Add Image"
              disabled={showPoll}
            >
              <ImageIcon className="w-5 h-5" />
            </Button>

            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowCw(!showCw)}
              className={cn(
                "rounded-full font-black text-[11px] uppercase tracking-widest px-3 h-8 gap-1.5 transition-all",
                showCw ? "bg-primary text-primary-foreground shadow-lg shadow-primary/20" : "text-muted-foreground hover:text-primary"
              )}
              title="Content Warning"
            >
              <AlertCircle className="w-3.5 h-3.5" />
              CW
            </Button>

            <Button
              variant="ghost"
              size="icon"
              onClick={() => setShowPoll(!showPoll)}
              className={cn(
                "rounded-full h-10 w-10 transition-all",
                showPoll ? "text-primary bg-primary/10" : "text-muted-foreground hover:text-primary"
              )}
              title="Poll"
              disabled={!!image}
            >
              <BarChart2 className="w-5 h-5" />
            </Button>

            <Popover open={showVisibilityMenu} onOpenChange={setShowVisibilityMenu}>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="rounded-full h-10 w-10 text-muted-foreground hover:text-primary"
                  title="Privacy"
                >
                  {getVisibilityIcon()}
                </Button>
              </PopoverTrigger>
              <PopoverContent side="top" align="start" className="w-[180px] p-1.5 rounded-2xl shadow-2xl border-border bg-background">
                {(['Public', 'Unlisted', 'Followers', 'Direct'] as const).map(opt => (
                  <Button
                    key={opt}
                    variant="ghost"
                    onClick={() => { setVisibility(opt); setShowVisibilityMenu(false); }}
                    className={cn(
                      "w-full justify-start gap-3 h-10 px-3 rounded-xl text-[13px] font-bold transition-all",
                      visibility === opt ? "bg-primary/10 text-primary shadow-sm" : "hover:bg-muted"
                    )}
                  >
                    <div className={cn("w-4 h-4", visibility === opt ? "text-primary" : "text-muted-foreground")}>
                      {opt === 'Public' ? <Globe className="w-4 h-4" /> :
                        opt === 'Unlisted' ? <LockKeyholeOpen className="w-4 h-4" /> :
                          opt === 'Followers' ? <Lock className="w-4 h-4" /> :
                            <AtSign className="w-4 h-4" />}
                    </div>
                    {opt}
                  </Button>
                ))}
              </PopoverContent>
            </Popover>
          </div>

          <div className="flex items-center gap-3">
            <div className={cn(
              "text-[10px] font-black font-mono tracking-tighter w-8 text-right",
              text.length > 480 ? "text-destructive scale-110" : "text-muted-foreground/40"
            )}>
              {500 - text.length}
            </div>
            <div className="w-px h-6 bg-border mx-1" />
            <Button variant="ghost" size="icon" className="h-9 w-9 text-muted-foreground rounded-full">
              <Smile className="w-5 h-5" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

