                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

            </main>

            {/* Share Modal */}
            {shareModalOpen && itemToShare && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 font-sans" onClick={() => { setShareModalOpen(false); setItemToShare(null); }}>
