﻿"use client";

import React, { useState } from 'react';
import { Screen } from '@/types';
import {
    FileText,
    Filter,
    Download,
    ArrowLeft,
    ChevronDown,
    StickyNote,
    SearchX
} from 'lucide-react';

interface Props {
    navigate: (screen: Screen) => void;
    goBack: () => void;
}

interface ModerationAction {
    id: string;
    action: string;
    moderator: {
        name: string;
        handle: string;
        avatar: string;
    };
    report: {
        type: 'comment' | 'link' | 'post';
        content: string;
        contextTitle: string;
    };
    timestamp: number;
    notes?: string;
}

// Mock data for now
const MOCK_ACTIONS: ModerationAction[] = [
    {
        id: '1',
        action: 'Delete',
        moderator: {
            name: 'Admin User',
            handle: '@admin',
            avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=admin',
        },
        report: {
            type: 'comment',
            content: 'This is spam content that was removed',
            contextTitle: 'The Art of Ife',
        },
        timestamp: Date.now() - 1000 * 60 * 30, // 30 mins ago
        notes: 'Clear violation of spam policy',
    },
    {
        id: '2',
        action: 'Warn User',
        moderator: {
            name: 'Moderator Jane',
            handle: '@jane_mod',
            avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=jane',
        },
        report: {
            type: 'comment',
            content: 'Inappropriate language used',
            contextTitle: 'Swahili Proverbs',
        },
        timestamp: Date.now() - 1000 * 60 * 60 * 2, // 2 hours ago
    },
    {
        id: '3',
        action: 'Approve',
        moderator: {
            name: 'Admin User',
            handle: '@admin',
            avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=admin',
        },
        report: {
            type: 'link',
            content: 'https://example.com/resource',
            contextTitle: 'Community Resources',
        },
        timestamp: Date.now() - 1000 * 60 * 60 * 5, // 5 hours ago
        notes: 'Legitimate educational resource',
    },
];


export const ModerationLogContent: React.FC<{ isEmbedded?: boolean }> = ({ isEmbedded = false }) => {
    const [actions] = useState<ModerationAction[]>(MOCK_ACTIONS);
    const [filterAction, setFilterAction] = useState<string>('All');
    const [showFilterMenu, setShowFilterMenu] = useState(false);

    const filteredActions = actions.filter(action =>
        filterAction === 'All' || action.action === filterAction
    );

    const getActionColor = (action: string) => {
        switch (action) {
            case 'Delete': return 'text-error';
            case 'Warn User': return 'text-warning';
            case 'Hide': return 'text-orange-500';
            case 'Approve': return 'text-success';
            default: return 'text-stone-600 dark:text-text-muted';
        }
    };

    const getActionBgColor = (action: string) => {
        switch (action) {
            case 'Delete': return 'bg-error/10';
            case 'Warn User': return 'bg-warning/10';
            case 'Hide': return 'bg-orange-500/10';
            case 'Approve': return 'bg-success/10';
            default: return 'bg-stone-100 dark:bg-white/5';
        }
    };

    const formatTimestamp = (timestamp: number) => {
        const diff = Date.now() - timestamp;
        const minutes = Math.floor(diff / (1000 * 60));
        const hours = Math.floor(diff / (1000 * 60 * 60));
        const days = Math.floor(diff / (1000 * 60 * 60 * 24));

        if (minutes < 60) return `${minutes}m ago`;
        if (hours < 24) return `${hours}h ago`;
        return `${days}d ago`;
    };

    return (
        <div className={`flex flex-col ${!isEmbedded ? 'min-h-screen bg-background-light dark:bg-background-dark' : 'h-full'} transition-colors duration-300`}>


            {/* Filter Bar */}
            <div className="px-4 py-3 flex gap-2 items-center border-b border-black/5 dark:border-white/5">
                <div className="relative flex-1">
                    <button
                        onClick={() => setShowFilterMenu(!showFilterMenu)}
                        className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium bg-black/5 dark:bg-[#473324] text-stone-900 dark:text-white hover:bg-black/10 dark:hover:bg-[#5a4230] transition-colors w-full"
                    >
                        <Filter className="w-4 h-4" />
                        <span className="flex-1 text-left">{filterAction === 'All' ? 'All Actions' : filterAction}</span>
                        <ChevronDown className={`w-4 h-4 transition-transform duration-200 ${showFilterMenu ? 'rotate-180' : ''}`} />
                    </button>

                    {showFilterMenu && (
                        <>
                            <div className="fixed inset-0 z-20" onClick={() => setShowFilterMenu(false)}></div>
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#32241a] shadow-xl rounded-xl z-30 border border-stone-200 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-150">
                                {['All', 'Delete', 'Hide', 'Approve', 'Warn User'].map(action => (
                                    <button
                                        key={action}
                                        onClick={() => { setFilterAction(action); setShowFilterMenu(false); }}
                                        className={`w-full text-left px-4 py-3 text-sm transition-colors ${filterAction === action
                                            ? 'bg-primary text-white font-bold'
                                            : 'hover:bg-black/5 dark:hover:bg-white/5 text-stone-800 dark:text-white'
                                            }`}
                                    >
                                        {action}
                                    </button>
                                ))}
                            </div>
                        </>
                    )}
                </div>


            </div>

            {/* Actions List */}
            <main className="flex-1 p-4 space-y-3 pb-24">
                {filteredActions.length > 0 ? (
                    filteredActions.map((action) => (
                        <div
                            key={action.id}
                            className="bg-white dark:bg-[#32241a] rounded-xl p-4 shadow-sm space-y-3 transition-colors animate-in fade-in slide-in-from-bottom-2"
                        >
                            {/* Header */}
                            <div className="flex items-start justify-between gap-3">
                                <div className="flex items-center gap-3 flex-1">
                                    <img
                                        src={action.moderator.avatar}
                                        alt={action.moderator.name}
                                        className="w-10 h-10 rounded-full"
                                    />
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm font-bold text-stone-900 dark:text-white truncate">
                                            {action.moderator.name}
                                        </p>
                                        <p className="text-xs text-stone-500 dark:text-text-muted">
                                            {action.moderator.handle}
                                        </p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <span className={`inline-block px-3 py-1 rounded-lg text-xs font-bold ${getActionBgColor(action.action)} ${getActionColor(action.action)}`}>
                                        {action.action}
                                    </span>
                                    <p className="text-xs text-stone-400 dark:text-text-muted/60 mt-1">
                                        {formatTimestamp(action.timestamp)}
                                    </p>
                                </div>
                            </div>

                            {/* Content */}
                            <div className="bg-stone-50 dark:bg-black/20 rounded-lg p-3">
                                <p className="text-xs text-stone-500 dark:text-text-muted font-bold mb-1">
                                    {action.report.type.toUpperCase()} • {action.report.contextTitle}
                                </p>
                                <p className="text-sm text-stone-700 dark:text-text-muted break-words">
                                    {action.report.content}
                                </p>
                            </div>

                            {/* Notes */}
                            {action.notes && (
                                <div className="flex items-start gap-2 text-xs text-stone-600 dark:text-text-muted">
                                    <StickyNote className="w-4 h-4 mt-0.5" />
                                    <p className="flex-1">{action.notes}</p>
                                </div>
                            )}
                        </div>
                    ))
                ) : (
                    <div className="flex flex-col items-center justify-center p-8 border-2 border-dashed border-stone-200 dark:border-white/10 rounded-xl mt-4">
                        <SearchX className="w-16 h-16 text-stone-300 dark:text-white/10 mb-4" />
                        <h3 className="text-lg font-bold text-stone-900 dark:text-white">No actions found</h3>
                        <p className="text-stone-600 dark:text-text-muted text-center">
                            No moderation actions match the selected filter
                        </p>
                    </div>
                )}
            </main>
        </div>
    );
};

const ModerationLogScreen: React.FC<Props> = ({ navigate, goBack }) => {
    return (
        <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark transition-colors duration-300">
            <header className="flex items-center p-4 sticky top-0 bg-background-light dark:bg-background-dark z-10 border-b border-black/5 dark:border-transparent">
                <button onClick={goBack} className="p-2 -ml-2 text-stone-900 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 rounded-full transition-colors">
                    <ArrowLeft className="w-6 h-6" />
                </button>
                <h1 className="flex-1 text-center text-lg font-bold text-stone-900 dark:text-white pr-8">
                    Moderation History
                </h1>
            </header>
            <ModerationLogContent />
        </div>
    );
};

export default ModerationLogScreen;

﻿"use client";

import React, { useState } from 'react';
import { Screen } from '@/types';
import {
    Shield,
    CheckCircle,
    AlertCircle,
    ArrowLeft,
    ClipboardList,
    ShieldCheck,
    Star,
    Medal,
    Trophy,
    Loader2
} from 'lucide-react';

interface Props {
    navigate: (screen: Screen) => void;
    goBack: () => void;
    userId?: string; // Current user's ID
}

const ModeratorApplicationScreen: React.FC<Props> = ({ navigate, goBack, userId }) => {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async () => {
        if (!userId) {
            setError('You must be logged in to apply');
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            // TODO: Call Convex mutation when integrated
            // const result = await applyForModerator({ userId });

            // Simulate API call
            await new Promise(resolve => setTimeout(resolve, 1000));

            setIsSubmitted(true);
        } catch (err: any) {
            setError(err.message || 'Failed to submit application');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (isSubmitted) {
        return (
            <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark">
                <header className="flex items-center p-4 border-b border-black/5 dark:border-transparent">
                    <button onClick={goBack} className="p-2 -ml-2 text-stone-900 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 rounded-full transition-colors">
                        <ArrowLeft className="w-6 h-6" />
                    </button>
                    <h1 className="flex-1 text-center text-lg font-bold text-stone-900 dark:text-white pr-8">
                        Application Submitted
                    </h1>
                </header>

                <main className="flex-1 flex flex-col items-center justify-center p-6">
                    <div className="w-20 h-20 rounded-full bg-success/20 flex items-center justify-center mb-6">
                        <CheckCircle className="w-12 h-12 text-success" />
                    </div>

                    <h2 className="text-2xl font-bold text-stone-900 dark:text-white mb-3 text-center">
                        Application Received!
                    </h2>

                    <p className="text-stone-600 dark:text-text-muted text-center max-w-md mb-8">
                        Thank you for your interest in becoming a moderator. Your application is pending review by our admin team.
                        We'll notify you once a decision has been made.
                    </p>

                    <button
                        onClick={() => navigate(Screen.SETTINGS)}
                        className="px-6 py-3 bg-primary text-white rounded-xl font-bold hover:bg-primary/90 transition-colors"
                    >
                        Back to Settings
                    </button>
                </main>
            </div>
        );
    }

    return (
        <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark">
            <header className="flex items-center p-4 border-b border-black/5 dark:border-transparent">
                <button onClick={goBack} className="p-2 -ml-2 text-stone-900 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 rounded-full transition-colors">
                    <ArrowLeft className="w-6 h-6" />
                </button>
                <h1 className="flex-1 text-center text-lg font-bold text-stone-900 dark:text-white pr-8">
                    Become a Moderator
                </h1>
            </header>

            <main className="flex-1 p-6 space-y-6 pb-24">
                {/* Hero Section */}
                <div className="text-center space-y-4">
                    <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center mx-auto">
                        <Shield className="w-10 h-10 text-primary" />
                    </div>

                    <h2 className="text-2xl font-bold text-stone-900 dark:text-white">
                        Help Keep Samiati Safe
                    </h2>

                    <p className="text-stone-600 dark:text-text-muted max-w-md mx-auto">
                        Moderators play a vital role in maintaining our community's cultural integrity and ensuring
                        respectful dialogue across all languages and traditions.
                    </p>
                </div>

                {/* Responsibilities */}
                <div className="bg-white dark:bg-[#32241a] rounded-xl p-6 space-y-4">
                    <h3 className="text-lg font-bold text-stone-900 dark:text-white flex items-center gap-2">
                        <ClipboardList className="w-5 h-5 text-primary" />
                        Moderator Responsibilities
                    </h3>

                    <ul className="space-y-3">
                        {[
                            'Review and action user reports promptly',
                            'Enforce community guidelines fairly and consistently',
                            'Protect cultural content from misinformation',
                            'Support users in resolving conflicts',
                            'Maintain confidentiality of moderation decisions'
                        ].map((item, index) => (
                            <li key={index} className="flex items-start gap-3 text-stone-700 dark:text-text-muted">
                                <CheckCircle className="w-5 h-5 text-success mt-0.5 flex-shrink-0" />
                                <span>{item}</span>
                            </li>
                        ))}
                    </ul>
                </div>

                {/* Requirements */}
                <div className="bg-white dark:bg-[#32241a] rounded-xl p-6 space-y-4">
                    <h3 className="text-lg font-bold text-stone-900 dark:text-white flex items-center gap-2">
                        <ShieldCheck className="w-5 h-5 text-primary" />
                        What We Look For
                    </h3>

                    <ul className="space-y-3">
                        {[
                            'Active participation in the Samiati community',
                            'Respect for diverse cultures and languages',
                            'Fair and unbiased judgment',
                            'Commitment to regular availability',
                            'Strong communication skills'
                        ].map((item, index) => (
                            <li key={index} className="flex items-start gap-3 text-stone-700 dark:text-text-muted">
                                <Star className="w-5 h-5 text-primary mt-0.5 flex-shrink-0" />
                                <span>{item}</span>
                            </li>
                        ))}
                    </ul>
                </div>

                {/* Benefits */}
                <div className="bg-gradient-to-br from-primary/10 to-primary/5 rounded-xl p-6 space-y-4">
                    <h3 className="text-lg font-bold text-stone-900 dark:text-white flex items-center gap-2">
                        <Medal className="w-5 h-5 text-primary" />
                        Moderator Benefits
                    </h3>

                    <ul className="space-y-3">
                        {[
                            'Exclusive moderator badge on your profile',
                            'Early access to new features',
                            'Direct communication with the Samiati team',
                            'Recognition in the community',
                            'Contribute to cultural preservation'
                        ].map((item, index) => (
                            <li key={index} className="flex items-start gap-3 text-stone-700 dark:text-text-muted">
                                <Trophy className="w-5 h-5 text-warning mt-0.5 flex-shrink-0" />
                                <span>{item}</span>
                            </li>
                        ))}
                    </ul>
                </div>

                {/* Error Message */}
                {error && (
                    <div className="bg-error/10 border border-error/20 rounded-xl p-4 flex items-start gap-3">
                        <AlertCircle className="w-5 h-5 text-error flex-shrink-0 mt-0.5" />
                        <p className="text-error text-sm">{error}</p>
                    </div>
                )}

                {/* Submit Button */}
                <button
                    onClick={handleSubmit}
                    disabled={isSubmitting}
                    className="w-full py-4 bg-primary text-white rounded-xl font-bold text-lg hover:bg-primary/90 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                    {isSubmitting ? (
                        <>
                            <Loader2 className="w-5 h-5 animate-spin" />
                            Submitting...
                        </>
                    ) : (
                        <>
                            <Shield className="w-5 h-5" />
                            Apply to Become a Moderator
                        </>
                    )}
                </button>

                {/* Disclaimer */}
                <p className="text-xs text-stone-500 dark:text-text-muted/60 text-center">
                    By applying, you agree to uphold Samiati's community guidelines and moderation policies.
                    Applications are reviewed by our admin team and approval is not guaranteed.
                </p>
            </main>
        </div>
    );
};

export default ModeratorApplicationScreen;

