const PeopleToFollowScreen: React.FC<Props> = ({ navigate, goBack, onViewProfile, initialFilter }) => {
  const isSelectContactMode = initialFilter === 'SelectContact';

  const [people, setPeople] = useState<Person[]>(MOCK_PEOPLE);
  const [activeCommunityTab, setActiveCommunityTab] = useState<'All' | 'People' | 'Communities'>('All');
  const [communities, setCommunities] = useState<Community[]>(INITIAL_COMMUNITIES);

  // Scroll Header Logic
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const scrollY = useRef(0);
  const mainRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const [headerHeight, setHeaderHeight] = useState(0);

  // Get active list for filters (Just people for now)
  const getActiveList = () => people;

  // Use custom hooks
  const filters = useWatuFilters(getActiveList());

  // Measure Header Height when layout changes
  useEffect(() => {
    if (headerRef.current) {
      setTimeout(() => {
        if (headerRef.current) setHeaderHeight(headerRef.current.offsetHeight);
      }, 50);
    }
  }, [activeCommunityTab, isSelectContactMode, filters.isSearchVisible]);

  // Scroll Handler
  const handleScroll = () => {
    if (!mainRef.current) return;
    const currentScrollY = mainRef.current.scrollTop;
    const diff = currentScrollY - scrollY.current;

    if (currentScrollY < 0) return;

    if (diff > 10 && currentScrollY > 50) {
      setIsHeaderVisible(false);
    } else if (diff < -10) {
      setIsHeaderVisible(true);
    }

    scrollY.current = currentScrollY;
  };

  const toggleFollow = (id: string) => {
    setPeople(prev => prev.map(p => p.id === id ? { ...p, isFollowing: !p.isFollowing } : p));
  };

  const handleUserClick = (person: Person) => {
    if (isSelectContactMode) {
      navigate(Screen.DIRECT_MESSAGE, {
        chatUser: {
          name: person.name,
          avatar: person.avatar,
          isOnline: false
        }
      });
    } else {
      onViewProfile({
        name: person.name,
        handle: person.handle,
        avatar: person.avatar,
        isGuest: false
      });
    }
  };

  const handleNavigate = (item: ContributionItem) => {
    if (item.type === 'Story') navigate(Screen.STORY_DETAIL);
    if (item.type === 'Word') navigate(Screen.WORD_DETAIL);
    if (item.type === 'Proverb') navigate(Screen.PROVERB_DETAIL);
  };

  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark text-stone-900 dark:text-white transition-colors duration-300 relative">
      {/* Scrollable Header Container */}
      <div
        ref={headerRef}
        className="absolute top-0 left-0 right-0 z-20 transition-all duration-300 ease-in-out bg-white dark:bg-background-dark shadow-sm border-b border-stone-200 dark:border-white/5"
        style={{ marginTop: isHeaderVisible ? 0 : -headerHeight }}
      >
        <WatuHeader
          isSelectContactMode={isSelectContactMode}
          peopleCount={people.length}
          isSearchVisible={filters.isSearchVisible}
          setIsSearchVisible={filters.setIsSearchVisible}
          searchQuery={filters.searchQuery}
          setSearchQuery={filters.setSearchQuery}
          goBack={goBack}
        />

        {/* Filter/Search Bar Container */}
        <div className="bg-background-light dark:bg-background-dark pb-2 transition-colors">
          {/* People / Communities Toggle */}
          {!isSelectContactMode && (
            <div className="px-4 py-2 flex items-center gap-2">
              {['All', 'People', 'Communities'].map(tab => (
                <button
                  key={tab}
                  onClick={() => setActiveCommunityTab(tab as any)}
                  className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${activeCommunityTab === tab
                    ? 'bg-stone-900 dark:bg-white text-white dark:text-stone-900 border-stone-900 dark:border-white'
                    : 'bg-transparent text-stone-500 dark:text-stone-400 border-stone-200 dark:border-white/10 hover:border-stone-400 dark:hover:border-white/30'
                    }`}
                >
                  {tab}
                </button>
              ))}
            </div>
          )}

          {/* Filters only if NOT in SelectContact mode */}
          {!isSelectContactMode && (
            <WatuFilters
              selectedRegion={filters.selectedRegion}
              setSelectedRegion={filters.setSelectedRegion}
              selectedLanguage={filters.selectedLanguage}
              setSelectedLanguage={filters.setSelectedLanguage}
              selectedRole={filters.selectedRole}
              setSelectedRole={filters.setSelectedRole}
              sortBy={filters.sortBy}
              setSortBy={filters.setSortBy}
              availableLanguages={filters.availableLanguages}
              activeFilterCount={filters.activeFilterCount}
              clearAllFilters={filters.clearAllFilters}
            />
          )}

          {isSelectContactMode && (
            <div className="px-4 py-2 font-bold text-sm text-stone-600 dark:text-text-muted bg-background-light dark:bg-background-dark">
              Contacts on Samiati
            </div>
          )}
        </div>
      </div>

      <main
        ref={mainRef}
        onScroll={handleScroll}
        className={`flex-1 overflow-y-auto p-4 space-y-4`}
        style={{ paddingTop: headerHeight + 16 }}
      >

        {/* Select Contact Options (WhatsApp Style) */}
        {isSelectContactMode && (
          <div className="bg-white dark:bg-surface-dark py-2 mb-4 rounded-xl shadow-sm border border-stone-100 dark:border-white/5">
            <button
              onClick={() => navigate(Screen.NEW_GROUP)}
              className="w-full px-4 py-3 flex items-center gap-4 hover:bg-stone-50 dark:hover:bg-white/5 transition-colors"
              aria-label="Create new group"
            >
              <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-white">
                <Users className="w-6 h-6" />
              </div>
              <span className="font-bold text-stone-900 dark:text-white">New group</span>
            </button>
            <button
              onClick={() => navigate(Screen.NEW_CONTACT)}
              className="w-full px-4 py-3 flex items-center gap-4 hover:bg-stone-50 dark:hover:bg-white/5 transition-colors"
              aria-label="Add new contact"
            >
              <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-white">
                <UserPlus className="w-6 h-6" />
              </div>
              <div className="flex flex-col items-start">
                <span className="font-bold text-stone-900 dark:text-white">New contact</span>
                <span className="text-xs text-stone-500 dark:text-text-muted"><QrCode className="w-3 h-3 align-middle mr-1 inline" />Scan QR code</span>
              </div>
            </button>
            <button
              onClick={() => navigate(Screen.NEW_COMMUNITY)}
              className="w-full px-4 py-3 flex items-center gap-4 hover:bg-stone-50 dark:hover:bg-white/5 transition-colors"
              aria-label="Create new community"
            >
              <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-white">
                <Users className="w-6 h-6" />
              </div>
              <span className="font-bold text-stone-900 dark:text-white">New community</span>
            </button>
          </div>
        )}

        {/* Empty State */}
        {((!isSelectContactMode &&
          ((activeCommunityTab === 'People' || activeCommunityTab === 'All') ? filters.filteredPeople.length > 0 : false) === false &&
          ((activeCommunityTab === 'Communities' || activeCommunityTab === 'All') ? communities.length > 0 : false) === false
        ) || (isSelectContactMode && filters.filteredPeople.length === 0)) && (
            <WatuEmptyState
              type="no-results"
              searchQuery={filters.searchQuery}
              onClearFilters={filters.activeFilterCount > 0 ? filters.clearAllFilters : undefined}
            />
          )}

        {/* Render People */}
        {(!isSelectContactMode && (activeCommunityTab === 'All' || activeCommunityTab === 'People')) || isSelectContactMode ? filters.filteredPeople.map(person => (
          <WatuUserCard
            key={person.id}
            person={person}
            isSelectContactMode={isSelectContactMode}
            onUserClick={handleUserClick}
            onToggleFollow={toggleFollow}
            onDM={(person) => {
              navigate(Screen.DIRECT_MESSAGE, {
                chatUser: {
                  name: person.name,
                  avatar: person.avatar,
                  isOnline: false
                }
              });
            }}
            showMutualConnections={!isSelectContactMode}
          />
        )) : null}

        {/* Render Communities */}
        {!isSelectContactMode && (activeCommunityTab === 'All' || activeCommunityTab === 'Communities') && communities.map(community => (
          <WatuUserCard
            key={community.id}
            person={{
              id: community.id,
              name: community.name,
              handle: 'Community',
              avatar: community.avatar,
              languages: [community.category || 'General'],
              region: community.memberCount + ' members',
              isFollowing: false,
              role: 'Community',
              about: community.description,
              contributionCount: 0
            }}
            isSelectContactMode={false}
            onUserClick={() => { }}
            onToggleFollow={() => { }}
            showMutualConnections={false}
          />
        ))}

        {isSelectContactMode && (
          <>
            <div className="px-4 py-4 text-xs font-bold text-stone-500 dark:text-text-muted">
              Invite to Samiati
            </div>
            <div className="px-4 py-3 flex items-center gap-4 opacity-50">
              <div className="w-10 h-10 rounded-full bg-stone-200 dark:bg-white/10 flex items-center justify-center text-stone-500 dark:text-text-muted">
                <Share2 className="w-6 h-6" />
              </div>
              <span className="font-bold text-stone-900 dark:text-white">Share invite link</span>
            </div>
          </>
        )}
      </main>
    </div>
  );
};

export default PeopleToFollowScreen;

﻿"use client";
import React, { useState, useEffect, useRef } from 'react';
import { Screen, Post } from '@/types';
import { PollComponent } from '@/components/social/PollComponent';
import {
    ArrowLeft,
    MoreVertical,
    Heart,
    MessageCircle,
    HandMetal,
    Share2,
    Send,
    Image as ImageIcon,
    MapPin,
    Sparkles,
    Bookmark,
    MoreHorizontal,
    VolumeX,
    Ban,
    Flag,
    Globe,
    CheckCircle2,
    Star,
    MessageSquare,
    Reply,
    Smile,
    Users,
    ChevronDown
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import { Badge } from "@/components/ui/badge";
import {
    Popover,
    PopoverTrigger,
    PopoverContent,
} from "@/components/ui/popover";
import { cn, copyToClipboard } from "@/lib/utils";

interface Props {
    navigate: (screen: Screen) => void;
    goBack: () => void;
    post: Post;
    onLike: (postId: string) => void;
    onRepost: (postId: string) => void;
    autoFocusReply?: boolean;
}

const PostThreadScreen: React.FC<Props> = ({ goBack, post, onLike, onRepost, autoFocusReply }) => {
    const [replyText, setReplyText] = useState('');
    const [activeMenuId, setActiveMenuId] = useState<string | null>(null);

    // Local state for UI interactions
    const [isContentExpanded, setIsContentExpanded] = useState(!post?.cw);
    const [showAltText, setShowAltText] = useState(false);
    const [isBookmarked, setIsBookmarked] = useState(false);
    const [toastMessage, setToastMessage] = useState<string | null>(null);

    const replyInputRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        const handleClickOutside = () => setActiveMenuId(null);
        if (activeMenuId) {
            document.addEventListener('click', handleClickOutside);
        }
        return () => document.removeEventListener('click', handleClickOutside);
    }, [activeMenuId]);

    useEffect(() => {
        if (autoFocusReply && replyInputRef.current) {
            setTimeout(() => {
                replyInputRef.current?.focus();
            }, 100);
        }
    }, [autoFocusReply]);

    const toggleMenu = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setActiveMenuId(prev => prev === id ? null : id);
    };

    const showToast = (msg: string) => {
        setToastMessage(msg);
        setTimeout(() => setToastMessage(null), 2000);
    };

    const handleMenuAction = (e: React.MouseEvent, action: string) => {
        e.stopPropagation();
        setActiveMenuId(null);
        if (action === 'share') {
            copyToClipboard(`https://samiati.app/post/${post.id}`);
            showToast('Link copied to clipboard');
        } else if (action === 'mute') {
            showToast(`Muted @${post.author.handle}`);
        } else if (action === 'block') {
            showToast(`Blocked @${post.author.handle}`);
        } else if (action === 'report') {
            showToast('Report submitted');
        }
    };

    const handleBookmark = () => {
        setIsBookmarked(!isBookmarked);
        showToast(isBookmarked ? 'Removed from Bookmarks' : 'Post Bookmarked');
    };

    const handleCommentClick = () => {
        replyInputRef.current?.focus();
    };

    const handlePublishReply = () => {
        if (!replyText.trim()) return;
        showToast('Reply sent!');
        setReplyText('');
    };

    const renderContentWithHashtags = (text: string) => {
        const parts = text.split(/(#\w+)/g);
        return parts.map((part, i) => {
            if (part.startsWith('#') && part.length > 1) {
                return (
                    <span
                        key={i}
                        className="text-primary font-bold hover:underline cursor-pointer"
                        onClick={(e) => {
                            e.stopPropagation();
                            alert(`Navigating to hashtag: ${part}`);
                        }}
                    >
                        {part}
                    </span>
                );
            }
            return part;
        });
    };

    const MenuDropdownContent = () => (
        <div className="flex flex-col p-1.5">
            <Button
                variant="ghost"
                onClick={(e) => handleMenuAction(e, 'share')}
                className="w-full justify-start gap-4 h-11 px-4 text-xs font-bold uppercase tracking-widest rounded-xl hover:bg-muted"
            >
                <Share2 className="w-4 h-4 text-muted-foreground" />
                Share Post
            </Button>
            <Button
                variant="ghost"
                onClick={(e) => handleMenuAction(e, 'mute')}
                className="w-full justify-start gap-4 h-11 px-4 text-xs font-bold uppercase tracking-widest rounded-xl hover:bg-muted"
            >
                <VolumeX className="w-4 h-4 text-muted-foreground" />
                Mute user
            </Button>
            <Button
                variant="ghost"
                onClick={(e) => handleMenuAction(e, 'block')}
                className="w-full justify-start gap-4 h-11 px-4 text-xs font-bold uppercase tracking-widest rounded-xl hover:bg-muted"
            >
                <Ban className="w-4 h-4 text-muted-foreground" />
                Block user
            </Button>
            <Separator className="my-1.5 opacity-50" />
            <Button
                variant="ghost"
                onClick={(e) => handleMenuAction(e, 'report')}
                className="w-full justify-start gap-4 h-11 px-4 text-xs font-bold uppercase tracking-widest rounded-xl text-destructive hover:bg-destructive/10 hover:text-destructive"
            >
                <Flag className="w-4 h-4" />
                Report Post
            </Button>
        </div>
    );

    if (!post) return null;

    const fullHandle = `@${post.author.handle}`;

    return (
        <div className="flex flex-col h-full bg-background transition-colors duration-300 relative">
            <header className="flex items-center px-4 h-14 sticky top-0 z-30 bg-background/95 backdrop-blur-md border-b border-border shrink-0">
                <Button variant="ghost" size="icon" onClick={goBack} className="text-primary hover:bg-primary/5">
                    <ArrowLeft className="w-5 h-5" />
                </Button>
                <h1 className="flex-1 text-center font-bold text-foreground text-sm tracking-tight">Post Details</h1>
                <div className="w-16"></div>
            </header>

            <main className="flex-1 overflow-y-auto pb-24">
                <div className="p-6 border-b border-border">
                    <div className="flex items-center gap-4 mb-6">
                        <Avatar className="w-14 h-14 rounded-2xl border border-border shadow-sm">
                            <AvatarImage src={post.author.avatar} className="object-cover" />
                            <AvatarFallback>{post.author.name[0]}</AvatarFallback>
                        </Avatar>
                        <div className="min-w-0">
                            <div className="font-black text-foreground text-lg tracking-tight leading-tight">{post.author.name}</div>
                            <div className="text-muted-foreground text-xs font-bold font-mono tracking-tighter opacity-70">{fullHandle}</div>
                        </div>
                    </div>

                    {/* CW Header */}
                    {post.cw && (
                        <div className="flex items-center justify-between mb-6 p-4 bg-muted/50 rounded-2xl border border-primary/10">
                            <div className="flex items-center gap-3">
                                <Badge variant="default" className="bg-primary/20 text-primary hover:bg-primary/20 border-none px-2.5 h-6 text-[10px] font-black uppercase tracking-widest">CW</Badge>
                                <span className="font-black text-xs text-foreground uppercase tracking-widest">{post.cw}</span>
                            </div>
                            <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => setIsContentExpanded(!isContentExpanded)}
                                className="text-primary font-black uppercase text-[10px] tracking-[0.2em] p-0 h-6 hover:bg-transparent"
                            >
                                {isContentExpanded ? 'Minimize' : 'Expand'}
                            </Button>
                        </div>
                    )}

                    {isContentExpanded && (
                        <div className="animate-in fade-in duration-300">
                            <div className="text-foreground text-xl leading-relaxed mb-6 whitespace-pre-wrap font-medium tracking-tight">
                                {renderContentWithHashtags(post.content)}
                            </div>

                            {post.poll && <PollComponent poll={post.poll} />}

                            {post.image && (
                                <div className="mb-6 rounded-3xl overflow-hidden border border-border shadow-2xl relative group bg-muted/10">
                                    <img src={post.image} alt={post.altText || "Post content"} className="w-full h-auto max-h-[600px] object-contain" />
                                    {post.altText && (
                                        <>
                                            <Button
                                                size="sm"
                                                variant="secondary"
                                                onClick={() => setShowAltText(!showAltText)}
                                                className="absolute bottom-4 left-4 h-8 bg-black/70 text-white text-[10px] font-black tracking-widest uppercase hover:bg-black/90 backdrop-blur-md rounded-xl"
                                            >
                                                ALT
                                            </Button>
                                            {showAltText && (
                                                <div className="absolute inset-0 bg-background/95 backdrop-blur-xl p-8 flex flex-col items-center justify-center text-foreground animate-in fade-in duration-300 cursor-default" onClick={() => setShowAltText(false)}>
                                                    <p className="text-sm font-bold uppercase tracking-widest text-muted-foreground mb-4">Image Description</p>
                                                    <p className="text-lg font-medium leading-relaxed italic text-center max-w-lg">{post.altText}</p>
