                                  <p className="text-xs text-text-main/90 leading-relaxed">{reply.text}</p>
                                </div>
                                <div className="flex items-center gap-3 mt-1 ml-2">
                                  <button className="text-[10px] font-bold text-text-muted hover:text-text-main">Like</button>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Related Section */}
        <div>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-text-main">Related Changa</h3>
            <button
              onClick={() => navigate(Screen.CONTRIBUTIONS)}
              className="text-primary text-sm font-bold hover:underline"
            >
              See All
            </button>
          </div>
          <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
            {RELATED_CONTENT.map((item, i) => (
              <div
                key={item.id}
                onClick={() => handleRelatedClick(item.type)}
                className="min-w-[160px] w-[160px] bg-surface-dark rounded-xl overflow-hidden border border-white/5 cursor-pointer hover:bg-white/10 transition-colors"
              >
                <div className="h-28 bg-cover bg-center" style={{ backgroundImage: `url('${item.img}')` }}></div>
                <div className="p-3">
                  <h4 className="font-bold text-sm text-text-main truncate mb-1">{item.title}</h4>
                  <p className="text-xs text-text-muted">{item.type}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      {/* Share Modal */}
      {isShareOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 font-sans" onClick={() => setIsShareOpen(false)}>
          <div
            className="bg-surface-dark w-full sm:max-w-sm rounded-t-2xl sm:rounded-2xl p-6 shadow-2xl animate-in slide-in-from-bottom-10 sm:zoom-in-95 duration-200 border border-white/5"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-text-main">Share Proverb</h3>
              <button onClick={() => setIsShareOpen(false)} className="p-1 rounded-full hover:bg-white/10 text-text-muted">
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>

            <div className="grid grid-cols-4 gap-4 mb-6">
              {[
                { name: 'WhatsApp', icon: 'chat', color: 'bg-[#25D366]', action: () => handleSocialShare('whatsapp') },
                { name: 'Twitter', icon: 'flutter_dash', color: 'bg-[#1DA1F2]', action: () => handleSocialShare('twitter') },
                { name: 'Facebook', icon: 'facebook', color: 'bg-[#1877F2]', action: () => handleSocialShare('facebook') },
                { name: 'Email', icon: 'mail', color: 'bg-stone-500', action: () => handleSocialShare('email') },
              ].map((platform) => (
                <button key={platform.name} onClick={platform.action} className="flex flex-col items-center gap-2 group">
                  <div className={`w-14 h-14 rounded-full ${platform.color} flex items-center justify-center text-white shadow-md transform group-hover:scale-110 transition-transform`}>
                    <span className="material-symbols-outlined text-2xl">{platform.icon}</span>
                  </div>
                  <span className="text-xs font-medium text-text-muted">{platform.name}</span>
                </button>
              ))}
            </div>

            <div className="bg-black/20 p-3 rounded-xl flex items-center gap-3 border border-white/5">
              <span className="material-symbols-outlined text-text-muted">link</span>
              <input
                type="text"
                value="https://samiati.app/proverb/gaskiya-ta-fi-kwabo"
                readOnly
                className="flex-1 bg-transparent text-sm text-text-muted outline-none truncate"
              />
              <button
                onClick={handleCopyLink}
                className="text-primary font-bold text-sm px-3 py-1.5 hover:bg-primary/10 rounded-lg transition-colors"
              >
                Copy
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      <div className={`fixed bottom-6 left-1/2 -translate-x-1/2 bg-text-main text-background-dark px-4 py-2 rounded-full shadow-lg font-bold text-sm transition-all duration-300 z-50 flex items-center gap-2 ${toastMessage ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
        <span className="material-symbols-outlined text-success">check_circle</span>
        {toastMessage}
      </div>
    </div>
  );
};

export default ProverbDetailScreen;

﻿"use client";
import React, { useState } from 'react';
import { Screen, Conversation } from '@/types';
import { useFuzzySearch } from '@/hooks/useFuzzySearch';
import {
    ArrowLeft,
    Search,
    Pin,
    Trash2,
    MessageSquare,
    Clock,
    ChevronRight,
    BookOpen,
    Music,
    Scroll,
    History,
    Type,
    Pencil,
    Check,
    X,
    MoreVertical,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface Props {
    navigate: (screen: Screen) => void;
    goBack: () => void;
    conversations: Conversation[];
    setConversations: (conversations: Conversation[]) => void;
    onChatSelect: (id: string) => void;
    onRename?: (id: string, newTitle: string) => void;
}

const SavedConversationsScreen: React.FC<Props> = ({
    navigate,
    goBack,
    conversations,
    setConversations,
    onChatSelect,
    onRename
}) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [activeTab, setActiveTab] = useState<'All' | 'Pinned' | 'Recent'>('All');

    const searchKeys = React.useMemo(() => ['title', 'category', 'language', 'messages.text'], []);
    const filtered = useFuzzySearch(conversations, searchQuery, searchKeys);

    let displayedConversations = filtered;
    if (activeTab === 'Recent') {
        displayedConversations = [...filtered].sort((a, b) => b.lastActive - a.lastActive);
    } else if (activeTab === 'Pinned') {
        displayedConversations = filtered.filter(c => c.isPinned);
    }

    const pinned = displayedConversations.filter(c => c.isPinned);
    const others = displayedConversations.filter(c => !c.isPinned);

    const handleDelete = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setConversations(conversations.filter(c => c.id !== id));
    };

    const handleTogglePin = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setConversations(conversations.map(c =>
            c.id === id ? { ...c, isPinned: !c.isPinned } : c
        ));
    };

    const handleShareStory = () => {
        navigate(Screen.ADD_CONTRIBUTION);
    };

    return (
        <div className="flex flex-col min-h-screen bg-background relative overflow-hidden font-body">
            {/* Abstract Background Shapes */}
            <div className="absolute top-[-5%] left-[-5%] w-[50%] h-[30%] bg-primary/5 blur-[100px] rounded-full pointer-events-none" />
            <div className="absolute bottom-[-5%] right-[-5%] w-[50%] h-[30%] bg-primary/10 blur-[100px] rounded-full pointer-events-none" />

            {/* Header */}
            <header className="sticky top-0 z-20 bg-background/80 backdrop-blur-lg px-4 py-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <Button
                        variant="ghost"
                        size="icon"
                        onClick={goBack}
                        className="rounded-full hover:bg-muted/50 transition-colors"
                    >
                        <ArrowLeft className="w-6 h-6" />
                    </Button>
                    <h1 className="text-xl font-black tracking-tight text-foreground">Kaendelee</h1>
                </div>
                <div className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground bg-muted/50 px-3 py-1 rounded-full border border-border/30">
                    {conversations.length} Saved
                </div>
            </header>

            {/* Main Content */}
            <main className="flex-1 relative z-10 p-4 max-w-2xl mx-auto w-full space-y-6 overflow-y-auto no-scrollbar pb-24">

                {/* Search Bar */}
                <div className="relative group animate-in fade-in slide-in-from-top-4 duration-500 delay-400">
                    <Search className="absolute left-4 top-3.5 h-5 w-5 text-muted-foreground group-focus-within:text-primary transition-colors" />
                    <Input
                        type="text"
                        placeholder="Find a conversation..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="h-12 pl-12 rounded-2xl bg-card/50 backdrop-blur-xl border-border/50 focus:bg-background transition-all shadow-sm"
                    />
                </div>

                {/* Categories / Tabs */}
                <div className="flex gap-2 animate-in fade-in slide-in-from-top-4 duration-500 delay-500">
                    {['All', 'Pinned', 'Recent'].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab as any)}
                            className={cn(
                                "px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 border",
                                activeTab === tab
                                    ? "bg-primary text-primary-foreground border-primary shadow-lg shadow-primary/20 scale-105"
                                    : "bg-card/50 text-muted-foreground border-border/50 hover:bg-muted/50"
                            )}
                        >
                            {tab}
                        </button>
                    ))}
                </div>

                {/* Conversation List */}
                <div className="space-y-4">
                    {/* Pinned Section */}
                    {activeTab !== 'Recent' && pinned.length > 0 && (
                        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                            <div className="flex items-center gap-2 px-1">
                                <Pin className="w-4 h-4 text-primary fill-primary" />
                                <h2 className="text-xs font-black uppercase tracking-widest text-muted-foreground">Pinned</h2>
                            </div>
                            {pinned.map((c, idx) => (
                                <ConversationCard
                                    key={c.id}
                                    conversation={c}
                                    onClick={() => onChatSelect(c.id)}
                                    onTogglePin={(e) => handleTogglePin(e, c.id)}
                                    onDelete={(e) => handleDelete(e, c.id)}
                                    onRename={onRename}
                                    index={idx}
                                />
                            ))}
                        </div>
                    )}

                    {/* Regular Section */}
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-700">
                        {others.length > 0 && (activeTab === 'All' || activeTab === 'Recent') && (
                            <>
                                <div className="flex items-center gap-2 px-1 mt-6">
                                    <Clock className="w-4 h-4 text-muted-foreground" />
                                    <h2 className="text-xs font-black uppercase tracking-widest text-muted-foreground">
                                        {activeTab === 'Recent' ? 'Most Recent' : 'All Conversations'}
                                    </h2>
                                </div>
                                {others.map((c, idx) => (
                                    <ConversationCard
                                        key={c.id}
                                        conversation={c}
                                        onClick={() => onChatSelect(c.id)}
                                        onTogglePin={(e) => handleTogglePin(e, c.id)}
                                        onDelete={(e) => handleDelete(e, c.id)}
                                        onRename={onRename}
                                        index={idx}
                                    />
                                ))}
                            </>
                        )}
                    </div>

                    {/* Empty State */}
                    {displayedConversations.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-20 px-6 text-center animate-in zoom-in duration-500">
                            <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mb-6">
                                <MessageSquare className="w-10 h-10 text-primary" />
                            </div>
                            <h3 className="text-xl font-black text-foreground mb-2">Start Preserving Heritage</h3>
                            <p className="text-muted-foreground text-sm max-w-[280px] mb-6">
                                {searchQuery
                                    ? "No conversations match your search. Try different keywords."
                                    : "Your cultural contributions will appear here. Every word you save is a gift to future generations."}
                            </p>
                            {!searchQuery && (
                                <Button onClick={handleShareStory} className="rounded-xl font-bold">
                                    Share Your First Story
                                </Button>
                            )}
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
};

interface CardProps {
    conversation: Conversation;
    onClick: () => void;
    onTogglePin: (e: React.MouseEvent) => void;
    onDelete: (e: React.MouseEvent) => void;
    onRename?: (id: string, newTitle: string) => void;
    index: number;
}

const ConversationCard: React.FC<CardProps> = ({
    conversation,
    onClick,
    onTogglePin,
    onDelete,
    onRename,
    index
}) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editTitle, setEditTitle] = useState(conversation.title);
    const inputRef = React.useRef<HTMLInputElement>(null);

    React.useEffect(() => {
        if (isEditing && inputRef.current) {
            inputRef.current.focus();
        }
    }, [isEditing]);

    const handleSaveRename = (e: React.MouseEvent | React.KeyboardEvent) => {
        e.stopPropagation();
        if (editTitle.trim() && onRename) {
            onRename(conversation.id, editTitle.trim());
            setIsEditing(false);
        }
    };

    const handleCancelRename = (e: React.MouseEvent | React.KeyboardEvent) => {
        e.stopPropagation();
        setEditTitle(conversation.title);
        setIsEditing(false);
    };

    const getCategoryIcon = (category?: string) => {
        switch (category?.toLowerCase()) {
            case 'history':
                return <History className="w-6 h-6" />;
            case 'music':
            case 'song':
                return <Music className="w-6 h-6" />;
            case 'literature':
            case 'story':
                return <BookOpen className="w-6 h-6" />;
            case 'stories':
            case 'proverb':
                return <Scroll className="w-6 h-6" />;
            default:
                return <MessageSquare className="w-6 h-6" />;
        }
    };

    const getCategoryColor = (category?: string) => {
        switch (category?.toLowerCase()) {
            case 'proverb': return 'bg-rasta-red/10 text-rasta-red';
            case 'story': return 'bg-rasta-gold/10 text-amber-600 dark:text-rasta-gold';
            case 'song': return 'bg-rasta-gold/20 text-amber-700 dark:text-rasta-gold/80';
            case 'history': return 'bg-rasta-red/20 text-red-800 dark:text-rasta-red/80';
            case 'word': return 'bg-rasta-green/10 text-rasta-green';
            default: return 'bg-primary/10 text-primary';
        }
    };

    // Safely get last message
    const lastMessage = conversation.messages && conversation.messages.length > 0
        ? conversation.messages[conversation.messages.length - 1].text
        : "No messages yet";

    return (
        <div
            onClick={!isEditing ? onClick : undefined}
            className={cn(
                "group relative bg-card/40 backdrop-blur-xl border border-border/50 rounded-2xl p-4 transition-all duration-300",
                !isEditing && "hover:bg-card/70 hover:border-primary/30 hover:shadow-xl hover:shadow-primary/5 active:scale-[0.99] cursor-pointer",
                "animate-in fade-in slide-in-from-bottom-4 duration-500"
            )}
            style={{ animationDelay: `${index * 50}ms` }}
        >
            <div className="flex items-center gap-4">
                {/* Avatar / Icon */}
                <div className={cn(
                    "w-12 h-12 rounded-xl flex items-center justify-center transition-transform duration-300",
                    !isEditing && "group-hover:scale-110",
                    getCategoryColor(conversation.category)
                )}>
                    {getCategoryIcon(conversation.category)}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                        {isEditing ? (
                            <div className="flex items-center gap-1 w-full" onClick={e => e.stopPropagation()}>
                                <Input
                                    ref={inputRef}
                                    value={editTitle}
                                    onChange={e => setEditTitle(e.target.value)}
                                    onKeyDown={e => {
                                        if (e.key === 'Enter') handleSaveRename(e);
                                        if (e.key === 'Escape') handleCancelRename(e);
                                        e.stopPropagation();
                                    }}
                                    className="h-7 text-base font-bold px-2 py-0 bg-background border-primary/50 focus-visible:ring-1 focus-visible:ring-primary"
                                />
                            </div>
                        ) : (
                            <>
                                <h3 className="text-base font-bold text-foreground truncate group-hover:text-primary transition-colors">
                                    {conversation.title}
                                </h3>
                                {conversation.language && (
                                    <span className="text-[9px] font-black uppercase tracking-wider bg-primary/10 text-primary px-2 py-0.5 rounded-md shrink-0">
                                        {conversation.language}
                                    </span>
                                )}
                            </>
                        )}
                    </div>
                    <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground mb-1">
                        <span className="flex items-center gap-1">
                            <Clock className="w-3 h-3" />
                            {conversation.messageCount} Messages
                        </span>

                        <span className="w-1 h-1 bg-border rounded-full" />
                        <span className="text-[10px]">{conversation.date}</span>
                    </div>
                    <p className="text-xs text-muted-foreground truncate opacity-70">
                        {lastMessage}
                    </p>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 ml-2 relative z-30" onClick={e => e.stopPropagation()}>
                    {isEditing ? (
                        <>
                            <button
                                onClick={handleSaveRename}
                                className="w-8 h-8 rounded-lg inline-flex items-center justify-center bg-primary/10 text-primary hover:bg-primary hover:text-white transition-colors"
                            >
                                <Check className="w-4 h-4" />
                            </button>
                            <button
                                onClick={handleCancelRename}
                                className="w-8 h-8 rounded-lg inline-flex items-center justify-center hover:bg-destructive/10 hover:text-destructive text-muted-foreground transition-colors"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        </>
                    ) : (
                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <button
                                    className="w-8 h-8 rounded-full inline-flex items-center justify-center text-muted-foreground/50 hover:text-foreground hover:bg-muted/50 transition-colors focus:outline-none"
                                    onClick={(e) => e.stopPropagation()}
                                >
                                    <MoreVertical className="w-4 h-4" />
                                </button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end" className="w-48">
                                <DropdownMenuItem onClick={(e) => {
                                    e.stopPropagation();
                                    setIsEditing(true);
                                }}>
                                    <Pencil className="mr-2 h-4 w-4" />
                                    <span>Rename</span>
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={(e) => {
                                    e.stopPropagation();
                                    onTogglePin(e);
                                }}>
                                    <Pin className={cn("mr-2 h-4 w-4", conversation.isPinned && "fill-primary text-primary")} />
                                    <span>{conversation.isPinned ? "Unpin" : "Pin"}</span>
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onDelete(e);
                                    }}
                                    className="text-destructive focus:text-destructive focus:bg-destructive/10"
                                >
                                    <Trash2 className="mr-2 h-4 w-4" />
                                    <span>Delete</span>
                                </DropdownMenuItem>
                            </DropdownMenuContent>
                        </DropdownMenu>
                    )}
                </div>
            </div>
        </div>
    );
};

export default SavedConversationsScreen;

